const root = process.cwd();
const files = {
  "components/enhancements/AlertDraftBridge.tsx": "\"use client\";\n\nimport { CheckCircle2, Clipboard, Trash2 } from \"lucide-react\";\nimport { usePathname } from \"next/navigation\";\nimport { useEffect, useState } from \"react\";\nimport { getLocaleFromPath } from \"@/components/enhancements/locale\";\n\ntype Draft = { symbol?: string; direction?: \"above\" | \"below\"; target?: number; note?: string };\n\nconst copy = {\n  tr: { title: \"Hazırladığın alarm taslağı\", above: \"üstüne çıkınca\", below: \"altına düşünce\", copy: \"Özeti kopyala\", copied: \"Kopyalandı\", clear: \"Taslağı temizle\", help: \"Aşağıdaki değerleri alarm formuna girerek alarmı etkinleştir.\" },\n  en: { title: \"Your prepared alert draft\", above: \"rises above\", below: \"falls below\", copy: \"Copy summary\", copied: \"Copied\", clear: \"Clear draft\", help: \"Enter these values in the alert form to activate the alert.\" },\n  el: { title: \"Το προσχέδιο ειδοποίησης\", above: \"ανέβει πάνω από\", below: \"πέσει κάτω από\", copy: \"Αντιγραφή\", copied: \"Αντιγράφηκε\", clear: \"Διαγραφή\", help: \"Βάλε αυτές τις τιμές στη φόρμα ειδοποίησης για ενεργοποίηση.\" }\n} as const;\n\nexport function AlertDraftBridge() {\n  const pathname = usePathname();\n  const locale = getLocaleFromPath(pathname);\n  const t = copy[locale];\n  const [draft, setDraft] = useState<Draft | null>(null);\n  const [copied, setCopied] = useState(false);\n  const isAlerts = pathname === `/${locale}/alerts` || pathname === \"/alerts\";\n\n  useEffect(() => {\n    if (!isAlerts) return;\n    try {\n      const stored = window.localStorage.getItem(\"btg_alert_wizard_draft_v1\");\n      if (stored) setDraft(JSON.parse(stored) as Draft);\n    } catch {\n      setDraft(null);\n    }\n  }, [isAlerts]);\n\n  if (!isAlerts || !draft?.symbol || !draft.target) return null;\n  const summary = `${draft.symbol} · ${draft.direction === \"below\" ? t.below : t.above} ${draft.target}${draft.note ? ` · ${draft.note}` : \"\"}`;\n\n  const clear = () => {\n    try { window.localStorage.removeItem(\"btg_alert_wizard_draft_v1\"); } catch {}\n    setDraft(null);\n  };\n\n  const copySummary = async () => {\n    try {\n      await navigator.clipboard.writeText(summary);\n      setCopied(true);\n      window.setTimeout(() => setCopied(false), 1500);\n    } catch {}\n  };\n\n  return (\n    <section className=\"mt-6 rounded-2xl border border-mint/25 bg-mint/[0.07] p-4 sm:p-5\" aria-live=\"polite\">\n      <div className=\"flex items-start gap-3\">\n        <CheckCircle2 className=\"mt-0.5 h-5 w-5 shrink-0 text-mint\" />\n        <div className=\"min-w-0 flex-1\">\n          <h2 className=\"font-black text-white\">{t.title}</h2>\n          <p className=\"mt-1 break-words text-sm font-bold text-mint\">{summary}</p>\n          <p className=\"mt-2 text-xs leading-5 text-slate-400\">{t.help}</p>\n          <div className=\"mt-3 flex flex-wrap gap-2\">\n            <button type=\"button\" onClick={() => void copySummary()} className=\"inline-flex items-center gap-2 rounded-xl border border-white/10 bg-white/5 px-3 py-2 text-xs font-bold text-white hover:text-mint\"><Clipboard className=\"h-3.5 w-3.5\" />{copied ? t.copied : t.copy}</button>\n            <button type=\"button\" onClick={clear} className=\"inline-flex items-center gap-2 rounded-xl border border-rose-300/20 bg-rose-300/10 px-3 py-2 text-xs font-bold text-rose-200\"><Trash2 className=\"h-3.5 w-3.5\" />{t.clear}</button>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n",
  "components/enhancements/AlertWizard.tsx": "\"use client\";\n\nimport Link from \"next/link\";\nimport { usePathname } from \"next/navigation\";\nimport { BellRing, Check, ChevronRight, Copy, Target } from \"lucide-react\";\nimport { useMemo, useState } from \"react\";\nimport { getLocaleFromPath, localizedHref } from \"@/components/enhancements/locale\";\n\ntype AssetType = \"coin\" | \"fx\" | \"gold\";\ntype Direction = \"above\" | \"below\";\n\nconst copy = {\n  tr: {\n    title: \"Kolay Alarm Sihirbazı\",\n    description: \"Üç adımda alarm taslağını hazırla, sonra mevcut alarm ekranında son kontrolü yap.\",\n    step1: \"1. Varlık\",\n    step2: \"2. Koşul\",\n    step3: \"3. Hedef\",\n    coin: \"Kripto\",\n    fx: \"Döviz\",\n    gold: \"Altın\",\n    symbol: \"Sembol\",\n    above: \"Bu fiyatın üstüne çıkınca\",\n    below: \"Bu fiyatın altına düşünce\",\n    target: \"Hedef fiyat\",\n    note: \"Not (isteğe bağlı)\",\n    notePlaceholder: \"Örn. alım fırsatını kontrol et\",\n    save: \"Taslağı kaydet\",\n    saved: \"Taslak kaydedildi\",\n    open: \"Alarm ekranını aç\",\n    copy: \"Özeti kopyala\",\n    copied: \"Kopyalandı\",\n    summary: \"Alarm özeti\",\n    invalid: \"Geçerli bir hedef fiyat gir.\",\n    draftInfo: \"Taslak bu cihazda saklanır. Alarmı gerçekten etkinleştirmek için alarm ekranında eklemen gerekir.\"\n  },\n  en: {\n    title: \"Easy Alert Wizard\",\n    description: \"Prepare an alert draft in three steps, then review it on the existing alerts screen.\",\n    step1: \"1. Asset\",\n    step2: \"2. Condition\",\n    step3: \"3. Target\",\n    coin: \"Crypto\",\n    fx: \"FX\",\n    gold: \"Gold\",\n    symbol: \"Symbol\",\n    above: \"When price rises above\",\n    below: \"When price falls below\",\n    target: \"Target price\",\n    note: \"Note (optional)\",\n    notePlaceholder: \"Example: review a buying opportunity\",\n    save: \"Save draft\",\n    saved: \"Draft saved\",\n    open: \"Open alerts\",\n    copy: \"Copy summary\",\n    copied: \"Copied\",\n    summary: \"Alert summary\",\n    invalid: \"Enter a valid target price.\",\n    draftInfo: \"The draft is stored on this device. Add it on the alerts screen to actually activate the alert.\"\n  },\n  el: {\n    title: \"Εύκολος οδηγός ειδοποίησης\",\n    description: \"Ετοίμασε ένα προσχέδιο ειδοποίησης σε τρία βήματα και έλεγξέ το στη σελίδα ειδοποιήσεων.\",\n    step1: \"1. Περιουσιακό στοιχείο\",\n    step2: \"2. Συνθήκη\",\n    step3: \"3. Στόχος\",\n    coin: \"Κρυπτονομίσματα\",\n    fx: \"Συνάλλαγμα\",\n    gold: \"Χρυσός\",\n    symbol: \"Σύμβολο\",\n    above: \"Όταν η τιμή ανέβει πάνω από\",\n    below: \"Όταν η τιμή πέσει κάτω από\",\n    target: \"Τιμή στόχος\",\n    note: \"Σημείωση (προαιρετικά)\",\n    notePlaceholder: \"Παράδειγμα: έλεγχος ευκαιρίας αγοράς\",\n    save: \"Αποθήκευση προσχεδίου\",\n    saved: \"Το προσχέδιο αποθηκεύτηκε\",\n    open: \"Άνοιγμα ειδοποιήσεων\",\n    copy: \"Αντιγραφή σύνοψης\",\n    copied: \"Αντιγράφηκε\",\n    summary: \"Σύνοψη ειδοποίησης\",\n    invalid: \"Βάλε έγκυρη τιμή στόχο.\",\n    draftInfo: \"Το προσχέδιο αποθηκεύεται σε αυτή τη συσκευή. Για ενεργοποίηση, πρόσθεσέ το στη σελίδα ειδοποιήσεων.\"\n  }\n} as const;\n\nconst symbols: Record<AssetType, string[]> = {\n  coin: [\"BTC\", \"ETH\", \"SOL\", \"BNB\", \"XRP\", \"TRX\"],\n  fx: [\"USD/TRY\", \"EUR/TRY\", \"GBP/TRY\", \"EUR/USD\"],\n  gold: [\"GRAM ALTIN\", \"ONS ALTIN\"]\n};\n\nexport function AlertWizard() {\n  const pathname = usePathname();\n  const locale = getLocaleFromPath(pathname);\n  const t = copy[locale];\n  const [assetType, setAssetType] = useState<AssetType>(\"coin\");\n  const [symbol, setSymbol] = useState(\"BTC\");\n  const [direction, setDirection] = useState<Direction>(\"above\");\n  const [target, setTarget] = useState(0);\n  const [note, setNote] = useState(\"\");\n  const [status, setStatus] = useState<\"idle\" | \"saved\" | \"copied\" | \"invalid\">(\"idle\");\n\n  const summary = useMemo(() => {\n    const condition = direction === \"above\" ? t.above : t.below;\n    return `${symbol} · ${condition} ${target || \"—\"}${note ? ` · ${note}` : \"\"}`;\n  }, [direction, note, symbol, t, target]);\n\n  const changeType = (type: AssetType) => {\n    setAssetType(type);\n    setSymbol(symbols[type][0]);\n    setStatus(\"idle\");\n  };\n\n  const saveDraft = () => {\n    if (!Number.isFinite(target) || target <= 0) {\n      setStatus(\"invalid\");\n      return;\n    }\n    try {\n      window.localStorage.setItem(\"btg_alert_wizard_draft_v1\", JSON.stringify({ assetType, symbol, direction, target, note, createdAt: new Date().toISOString() }));\n    } catch {\n      // The summary remains usable even when browser storage is unavailable.\n    }\n    setStatus(\"saved\");\n  };\n\n  const copySummary = async () => {\n    try {\n      await navigator.clipboard.writeText(summary);\n      setStatus(\"copied\");\n    } catch {\n      setStatus(\"idle\");\n    }\n  };\n\n  return (\n    <section className=\"rounded-3xl border border-white/10 bg-slate-950/45 p-5 shadow-card sm:p-7\">\n      <div className=\"flex items-start gap-3\">\n        <span className=\"rounded-2xl border border-mint/20 bg-mint/10 p-3 text-mint\"><BellRing className=\"h-6 w-6\" /></span>\n        <div>\n          <h2 className=\"text-2xl font-black text-white\">{t.title}</h2>\n          <p className=\"mt-2 text-sm leading-7 text-slate-400\">{t.description}</p>\n        </div>\n      </div>\n\n      <div className=\"mt-6 grid gap-5 lg:grid-cols-3\">\n        <div className=\"rounded-2xl border border-white/10 bg-white/[0.035] p-4\">\n          <p className=\"text-xs font-black uppercase tracking-[0.18em] text-mint\">{t.step1}</p>\n          <div className=\"mt-3 grid grid-cols-3 gap-2\">\n            {([\"coin\", \"fx\", \"gold\"] as AssetType[]).map((type) => (\n              <button key={type} type=\"button\" onClick={() => changeType(type)} className={`rounded-xl border px-2 py-2 text-xs font-bold transition ${assetType === type ? \"border-mint/40 bg-mint/15 text-mint\" : \"border-white/10 bg-slate-950 text-slate-400\"}`}>\n                {t[type]}\n              </button>\n            ))}\n          </div>\n          <label className=\"mt-4 block text-sm font-semibold text-slate-300\">\n            {t.symbol}\n            <select value={symbol} onChange={(event) => setSymbol(event.target.value)} className=\"mt-2 w-full rounded-xl border border-white/10 bg-slate-950 px-3 py-3 text-white outline-none focus:border-mint/60\">\n              {symbols[assetType].map((item) => <option key={item} value={item}>{item}</option>)}\n            </select>\n          </label>\n        </div>\n\n        <div className=\"rounded-2xl border border-white/10 bg-white/[0.035] p-4\">\n          <p className=\"text-xs font-black uppercase tracking-[0.18em] text-mint\">{t.step2}</p>\n          <div className=\"mt-3 space-y-2\">\n            {([\"above\", \"below\"] as Direction[]).map((item) => (\n              <button key={item} type=\"button\" onClick={() => setDirection(item)} className={`flex w-full items-center justify-between rounded-xl border px-3 py-3 text-left text-sm font-bold transition ${direction === item ? \"border-mint/40 bg-mint/15 text-mint\" : \"border-white/10 bg-slate-950 text-slate-400\"}`}>\n                {t[item]}{direction === item ? <Check className=\"h-4 w-4\" /> : null}\n              </button>\n            ))}\n          </div>\n        </div>\n\n        <div className=\"rounded-2xl border border-white/10 bg-white/[0.035] p-4\">\n          <p className=\"text-xs font-black uppercase tracking-[0.18em] text-mint\">{t.step3}</p>\n          <label className=\"mt-3 block text-sm font-semibold text-slate-300\">\n            {t.target}\n            <input type=\"number\" min=\"0\" step=\"any\" value={target || \"\"} onChange={(event) => setTarget(Number(event.target.value))} className=\"mt-2 w-full rounded-xl border border-white/10 bg-slate-950 px-3 py-3 text-white outline-none focus:border-mint/60\" />\n          </label>\n          <label className=\"mt-3 block text-sm font-semibold text-slate-300\">\n            {t.note}\n            <input value={note} onChange={(event) => setNote(event.target.value)} placeholder={t.notePlaceholder} className=\"mt-2 w-full rounded-xl border border-white/10 bg-slate-950 px-3 py-3 text-white outline-none placeholder:text-slate-600 focus:border-mint/60\" />\n          </label>\n        </div>\n      </div>\n\n      <div className=\"mt-5 rounded-2xl border border-mint/15 bg-mint/[0.06] p-4\">\n        <div className=\"flex items-center gap-2 text-mint\"><Target className=\"h-4 w-4\" /><p className=\"text-xs font-black uppercase tracking-[0.18em]\">{t.summary}</p></div>\n        <p className=\"mt-2 text-sm font-bold text-white\">{summary}</p>\n        <p className=\"mt-2 text-xs leading-5 text-slate-400\">{t.draftInfo}</p>\n      </div>\n\n      {status === \"invalid\" ? <p className=\"mt-3 text-sm font-bold text-rose-300\">{t.invalid}</p> : null}\n      <div className=\"mt-5 flex flex-col gap-2 sm:flex-row sm:flex-wrap\">\n        <button type=\"button\" onClick={saveDraft} className=\"inline-flex items-center justify-center gap-2 rounded-xl bg-mint px-4 py-3 font-black text-slate-950 transition hover:brightness-110\">\n          {status === \"saved\" ? <Check className=\"h-4 w-4\" /> : <BellRing className=\"h-4 w-4\" />}{status === \"saved\" ? t.saved : t.save}\n        </button>\n        <button type=\"button\" onClick={() => void copySummary()} className=\"inline-flex items-center justify-center gap-2 rounded-xl border border-white/10 bg-white/5 px-4 py-3 font-bold text-white transition hover:border-mint/30 hover:text-mint\">\n          {status === \"copied\" ? <Check className=\"h-4 w-4\" /> : <Copy className=\"h-4 w-4\" />}{status === \"copied\" ? t.copied : t.copy}\n        </button>\n        <Link href={`${localizedHref(pathname, \"/alerts\")}?draft=1`} className=\"inline-flex items-center justify-center gap-2 rounded-xl border border-white/10 bg-white/5 px-4 py-3 font-bold text-white transition hover:border-mint/30 hover:text-mint\">\n          {t.open}<ChevronRight className=\"h-4 w-4\" />\n        </Link>\n      </div>\n    </section>\n  );\n}\n",
  "components/enhancements/DataPrivacyControls.tsx": "\"use client\";\n\nimport Link from \"next/link\";\nimport { usePathname } from \"next/navigation\";\nimport { CheckCircle2, Cloud, ShieldCheck, Trash2 } from \"lucide-react\";\nimport { useState } from \"react\";\nimport { getLocaleFromPath, localizedHref } from \"@/components/enhancements/locale\";\n\nconst copy = {\n  tr: {\n    title: \"Bu cihazdaki site verilerini temizle\",\n    description: \"Favoriler, yerel portföy, alarm taslakları, tema, dil ve panel tercihleri bu tarayıcıdan kaldırılır.\",\n    button: \"Yerel verileri temizle\",\n    done: \"Yerel veriler temizlendi\",\n    cloudTitle: \"Bulut verileri\",\n    cloudDescription: \"Bu işlem Supabase hesabındaki senkronize verileri sunucudan silmez. Bulut verisi veya hesabın tamamen silinmesi için iletişim sayfasından talep gönder.\",\n    contact: \"Silme talebi gönder\"\n  },\n  en: {\n    title: \"Clear site data on this device\",\n    description: \"Favorites, local portfolio, alert drafts, theme, language and dashboard preferences are removed from this browser.\",\n    button: \"Clear local data\",\n    done: \"Local data cleared\",\n    cloudTitle: \"Cloud data\",\n    cloudDescription: \"This action does not remove synchronized Supabase data from the server. Use the contact page to request deletion of cloud data or the whole account.\",\n    contact: \"Send a deletion request\"\n  },\n  el: {\n    title: \"Διαγραφή δεδομένων ιστοτόπου από τη συσκευή\",\n    description: \"Αγαπημένα, τοπικό χαρτοφυλάκιο, προσχέδια ειδοποιήσεων, θέμα, γλώσσα και προτιμήσεις πίνακα αφαιρούνται από αυτόν τον browser.\",\n    button: \"Διαγραφή τοπικών δεδομένων\",\n    done: \"Τα τοπικά δεδομένα διαγράφηκαν\",\n    cloudTitle: \"Δεδομένα cloud\",\n    cloudDescription: \"Η ενέργεια δεν διαγράφει συγχρονισμένα δεδομένα Supabase από τον server. Χρησιμοποίησε τη σελίδα επικοινωνίας για αίτημα διαγραφής δεδομένων cloud ή λογαριασμού.\",\n    contact: \"Αποστολή αιτήματος διαγραφής\"\n  }\n} as const;\n\nexport function DataPrivacyControls() {\n  const pathname = usePathname();\n  const locale = getLocaleFromPath(pathname);\n  const t = copy[locale];\n  const [done, setDone] = useState(false);\n\n  const clearLocalData = async () => {\n    try { window.localStorage.clear(); } catch { /* Storage can be blocked by the browser. */ }\n    try { window.sessionStorage.clear(); } catch { /* Storage can be blocked by the browser. */ }\n    try {\n      document.cookie.split(\";\").forEach((entry) => {\n        const name = entry.split(\"=\")[0]?.trim();\n        if (name) document.cookie = `${name}=; Max-Age=0; path=/; SameSite=Lax`;\n      });\n    } catch {}\n    if (\"caches\" in window) {\n      try {\n        const names = await window.caches.keys();\n        await Promise.all(names.map((name) => window.caches.delete(name)));\n      } catch {}\n    }\n    setDone(true);\n  };\n\n  return (\n    <section className=\"grid gap-4 lg:grid-cols-2\">\n      <article className=\"rounded-2xl border border-rose-300/20 bg-rose-300/[0.06] p-5 sm:p-6\">\n        <div className=\"flex items-start gap-3\">\n          <span className=\"rounded-xl bg-rose-300/10 p-2.5 text-rose-200\"><Trash2 className=\"h-5 w-5\" /></span>\n          <div><h2 className=\"text-lg font-black text-white\">{t.title}</h2><p className=\"mt-2 text-sm leading-7 text-slate-300\">{t.description}</p></div>\n        </div>\n        <button type=\"button\" onClick={() => void clearLocalData()} className=\"mt-5 inline-flex items-center gap-2 rounded-xl border border-rose-300/25 bg-rose-300/10 px-4 py-3 font-black text-rose-100 transition hover:bg-rose-300/15\">\n          {done ? <CheckCircle2 className=\"h-4 w-4\" /> : <Trash2 className=\"h-4 w-4\" />}{done ? t.done : t.button}\n        </button>\n      </article>\n      <article className=\"rounded-2xl border border-mint/20 bg-mint/[0.06] p-5 sm:p-6\">\n        <div className=\"flex items-start gap-3\">\n          <span className=\"rounded-xl bg-mint/10 p-2.5 text-mint\"><Cloud className=\"h-5 w-5\" /></span>\n          <div><h2 className=\"text-lg font-black text-white\">{t.cloudTitle}</h2><p className=\"mt-2 text-sm leading-7 text-slate-300\">{t.cloudDescription}</p></div>\n        </div>\n        <Link href={localizedHref(pathname, \"/contact\")} className=\"mt-5 inline-flex items-center gap-2 rounded-xl bg-mint px-4 py-3 font-black text-slate-950 transition hover:brightness-110\"><ShieldCheck className=\"h-4 w-4\" />{t.contact}</Link>\n      </article>\n    </section>\n  );\n}\n",
  "components/enhancements/FinanceCalculatorHub.tsx": "\"use client\";\n\nimport { usePathname } from \"next/navigation\";\nimport { useMemo, useState, type ReactNode } from \"react\";\nimport { Banknote, Calculator, CreditCard, Landmark, PiggyBank, Scale, TrendingUp } from \"lucide-react\";\nimport { getLocaleFromPath, type BtgLocale } from \"@/components/enhancements/locale\";\n\ntype ToolKey = \"deposit\" | \"compound\" | \"goal\" | \"fx\" | \"inflation\" | \"card\" | \"gold\";\n\nconst translations = {\n  tr: {\n    title: \"Finans Hesaplama Merkezi\",\n    description: \"Mevduat, bileşik getiri, birikim hedefi, kur kârı, enflasyon ve kart faizini tek yerde yaklaşık olarak hesapla.\",\n    disclaimer: \"Sonuçlar yaklaşık ve bilgilendirme amaçlıdır. Banka, vergi, fon, kesinti ve yuvarlama kuralları gerçek sonucu değiştirebilir.\",\n    calculate: \"Sonuç\",\n    principal: \"Ana para\",\n    annualRate: \"Yıllık brüt oran (%)\",\n    days: \"Gün\",\n    withholding: \"Stopaj (%)\",\n    gross: \"Brüt kazanç\",\n    net: \"Net kazanç\",\n    final: \"Vade sonu toplam\",\n    months: \"Ay\",\n    monthlyContribution: \"Aylık ekleme\",\n    target: \"Hedef tutar\",\n    estimatedMonths: \"Tahmini süre\",\n    buyRate: \"Alış fiyatı\",\n    sellRate: \"Güncel/satış fiyatı\",\n    quantity: \"Miktar\",\n    profit: \"Kâr / zarar\",\n    futureValue: \"Gelecekteki tutar\",\n    inflation: \"Yıllık enflasyon (%)\",\n    years: \"Yıl\",\n    realValue: \"Bugünkü satın alma gücü\",\n    balance: \"Kart borcu\",\n    monthlyRate: \"Aylık faiz (%)\",\n    estimatedInterest: \"Yaklaşık bir aylık faiz\",\n    grams: \"Gram\",\n    cost: \"Toplam maliyet\",\n    currentValue: \"Güncel değer\",\n    deposit: \"Mevduat\",\n    compound: \"Bileşik getiri\",\n    goal: \"Birikim hedefi\",\n    fx: \"Döviz kârı\",\n    inflationTool: \"Enflasyon\",\n    card: \"Kart faizi\",\n    gold: \"Altın maliyeti\",\n    unreachable: \"Bu girdilerle hedefe ulaşma süresi hesaplanamadı.\",\n    monthSuffix: \"ay\"\n  },\n  en: {\n    title: \"Finance Calculator Center\",\n    description: \"Estimate deposits, compound growth, savings goals, FX profit, inflation and card interest in one place.\",\n    disclaimer: \"Results are estimates for information only. Bank, tax, fee and rounding rules can change the actual result.\",\n    calculate: \"Result\",\n    principal: \"Principal\",\n    annualRate: \"Annual gross rate (%)\",\n    days: \"Days\",\n    withholding: \"Withholding tax (%)\",\n    gross: \"Gross return\",\n    net: \"Net return\",\n    final: \"Final amount\",\n    months: \"Months\",\n    monthlyContribution: \"Monthly contribution\",\n    target: \"Target amount\",\n    estimatedMonths: \"Estimated time\",\n    buyRate: \"Buy price\",\n    sellRate: \"Current/sell price\",\n    quantity: \"Quantity\",\n    profit: \"Profit / loss\",\n    futureValue: \"Future amount\",\n    inflation: \"Annual inflation (%)\",\n    years: \"Years\",\n    realValue: \"Present purchasing power\",\n    balance: \"Card balance\",\n    monthlyRate: \"Monthly rate (%)\",\n    estimatedInterest: \"Estimated one-month interest\",\n    grams: \"Grams\",\n    cost: \"Total cost\",\n    currentValue: \"Current value\",\n    deposit: \"Deposit\",\n    compound: \"Compound growth\",\n    goal: \"Savings goal\",\n    fx: \"FX profit\",\n    inflationTool: \"Inflation\",\n    card: \"Card interest\",\n    gold: \"Gold cost\",\n    unreachable: \"The target could not be reached with these inputs.\",\n    monthSuffix: \"months\"\n  },\n  el: {\n    title: \"Κέντρο οικονομικών υπολογισμών\",\n    description: \"Υπολόγισε κατά προσέγγιση καταθέσεις, σύνθετη απόδοση, στόχους αποταμίευσης, κέρδος συναλλάγματος, πληθωρισμό και τόκους κάρτας.\",\n    disclaimer: \"Τα αποτελέσματα είναι ενδεικτικά. Τραπεζικοί, φορολογικοί και λοιποί κανόνες μπορεί να αλλάξουν το πραγματικό αποτέλεσμα.\",\n    calculate: \"Αποτέλεσμα\",\n    principal: \"Αρχικό κεφάλαιο\",\n    annualRate: \"Ετήσιο μικτό επιτόκιο (%)\",\n    days: \"Ημέρες\",\n    withholding: \"Παρακράτηση (%)\",\n    gross: \"Μικτή απόδοση\",\n    net: \"Καθαρή απόδοση\",\n    final: \"Τελικό ποσό\",\n    months: \"Μήνες\",\n    monthlyContribution: \"Μηνιαία συνεισφορά\",\n    target: \"Στόχος\",\n    estimatedMonths: \"Εκτιμώμενος χρόνος\",\n    buyRate: \"Τιμή αγοράς\",\n    sellRate: \"Τρέχουσα/τιμή πώλησης\",\n    quantity: \"Ποσότητα\",\n    profit: \"Κέρδος / ζημία\",\n    futureValue: \"Μελλοντικό ποσό\",\n    inflation: \"Ετήσιος πληθωρισμός (%)\",\n    years: \"Έτη\",\n    realValue: \"Σημερινή αγοραστική δύναμη\",\n    balance: \"Υπόλοιπο κάρτας\",\n    monthlyRate: \"Μηνιαίο επιτόκιο (%)\",\n    estimatedInterest: \"Εκτιμώμενος τόκος ενός μήνα\",\n    grams: \"Γραμμάρια\",\n    cost: \"Συνολικό κόστος\",\n    currentValue: \"Τρέχουσα αξία\",\n    deposit: \"Κατάθεση\",\n    compound: \"Σύνθετη απόδοση\",\n    goal: \"Στόχος αποταμίευσης\",\n    fx: \"Κέρδος συναλλάγματος\",\n    inflationTool: \"Πληθωρισμός\",\n    card: \"Τόκος κάρτας\",\n    gold: \"Κόστος χρυσού\",\n    unreachable: \"Ο στόχος δεν μπορεί να υπολογιστεί με αυτά τα δεδομένα.\",\n    monthSuffix: \"μήνες\"\n  }\n} as const;\n\nfunction useNumericState(initial: number) {\n  const [value, setValue] = useState(initial);\n  return [value, (raw: string) => setValue(Number.isFinite(Number(raw)) ? Number(raw) : 0)] as const;\n}\n\nfunction money(value: number, locale: BtgLocale, currency = \"TRY\") {\n  const localeCode = locale === \"tr\" ? \"tr-TR\" : locale === \"el\" ? \"el-GR\" : \"en-US\";\n  return new Intl.NumberFormat(localeCode, { style: \"currency\", currency, maximumFractionDigits: 2 }).format(Number.isFinite(value) ? value : 0);\n}\n\nfunction Field({ label, value, onChange, min = 0, step = \"any\" }: { label: string; value: number; onChange: (value: string) => void; min?: number; step?: string }) {\n  return (\n    <label className=\"block text-sm font-semibold text-slate-300\">\n      {label}\n      <input type=\"number\" min={min} step={step} value={value} onChange={(event) => onChange(event.target.value)} className=\"mt-2 w-full rounded-xl border border-white/10 bg-slate-950/90 px-3 py-3 text-white outline-none transition focus:border-mint/60\" />\n    </label>\n  );\n}\n\nfunction ResultBox({ title, children }: { title: string; children: ReactNode }) {\n  return (\n    <div className=\"rounded-2xl border border-mint/20 bg-mint/[0.07] p-5\">\n      <p className=\"text-xs font-black uppercase tracking-[0.18em] text-mint\">{title}</p>\n      <div className=\"mt-3 space-y-2 text-sm text-slate-300\">{children}</div>\n    </div>\n  );\n}\n\nexport function FinanceCalculatorHub() {\n  const pathname = usePathname();\n  const locale = getLocaleFromPath(pathname);\n  const t = translations[locale];\n  const [active, setActive] = useState<ToolKey>(\"deposit\");\n\n  const [principal, setPrincipal] = useNumericState(150000);\n  const [annualRate, setAnnualRate] = useNumericState(40);\n  const [days, setDays] = useNumericState(30);\n  const [withholding, setWithholding] = useNumericState(17.5);\n  const [months, setMonths] = useNumericState(12);\n  const [monthlyContribution, setMonthlyContribution] = useNumericState(5000);\n  const [target, setTarget] = useNumericState(250000);\n  const [buyRate, setBuyRate] = useNumericState(35);\n  const [sellRate, setSellRate] = useNumericState(40);\n  const [quantity, setQuantity] = useNumericState(1000);\n  const [futureValue, setFutureValue] = useNumericState(250000);\n  const [inflation, setInflation] = useNumericState(30);\n  const [years, setYears] = useNumericState(1);\n  const [balance, setBalance] = useNumericState(10000);\n  const [monthlyRate, setMonthlyRate] = useNumericState(4.25);\n  const [grams, setGrams] = useNumericState(10);\n\n  const deposit = useMemo(() => {\n    const gross = principal * (annualRate / 100) * (days / 365);\n    const net = gross * (1 - withholding / 100);\n    return { gross, net, final: principal + net };\n  }, [annualRate, days, principal, withholding]);\n\n  const compound = useMemo(() => {\n    const monthly = annualRate / 100 / 12;\n    let total = principal;\n    for (let month = 0; month < Math.max(0, Math.floor(months)); month += 1) {\n      total = total * (1 + monthly) + monthlyContribution;\n    }\n    return { total, gain: total - principal - monthlyContribution * Math.max(0, Math.floor(months)) };\n  }, [annualRate, monthlyContribution, months, principal]);\n\n  const goalMonths = useMemo(() => {\n    if (target <= principal) return 0;\n    const monthly = annualRate / 100 / 12;\n    let total = principal;\n    for (let month = 1; month <= 1200; month += 1) {\n      total = total * (1 + monthly) + monthlyContribution;\n      if (total >= target) return month;\n    }\n    return null;\n  }, [annualRate, monthlyContribution, principal, target]);\n\n  const fxProfit = (sellRate - buyRate) * quantity;\n  const fxCost = buyRate * quantity;\n  const fxValue = sellRate * quantity;\n  const purchasingPower = futureValue / Math.pow(1 + inflation / 100, Math.max(0, years));\n  const cardInterest = balance * monthlyRate / 100;\n  const goldCost = grams * buyRate;\n  const goldValue = grams * sellRate;\n  const goldProfit = goldValue - goldCost;\n\n  const tools: Array<{ key: ToolKey; label: string; icon: typeof Calculator }> = [\n    { key: \"deposit\", label: t.deposit, icon: Landmark },\n    { key: \"compound\", label: t.compound, icon: TrendingUp },\n    { key: \"goal\", label: t.goal, icon: PiggyBank },\n    { key: \"fx\", label: t.fx, icon: Banknote },\n    { key: \"inflation\", label: t.inflationTool, icon: Scale },\n    { key: \"card\", label: t.card, icon: CreditCard },\n    { key: \"gold\", label: t.gold, icon: Calculator }\n  ];\n\n  return (\n    <section className=\"rounded-3xl border border-white/10 bg-slate-950/45 p-5 shadow-card sm:p-7\">\n      <div className=\"max-w-3xl\">\n        <h2 className=\"text-2xl font-black text-white sm:text-3xl\">{t.title}</h2>\n        <p className=\"mt-2 text-sm leading-7 text-slate-400\">{t.description}</p>\n      </div>\n      <div className=\"mt-6 flex gap-2 overflow-x-auto pb-2\">\n        {tools.map(({ key, label, icon: Icon }) => (\n          <button key={key} type=\"button\" onClick={() => setActive(key)} className={`inline-flex shrink-0 items-center gap-2 rounded-xl border px-3 py-2.5 text-sm font-bold transition ${active === key ? \"border-mint/40 bg-mint/15 text-mint\" : \"border-white/10 bg-white/5 text-slate-400 hover:text-white\"}`}>\n            <Icon className=\"h-4 w-4\" />{label}\n          </button>\n        ))}\n      </div>\n\n      <div className=\"mt-5 grid gap-5 lg:grid-cols-[1fr_0.8fr]\">\n        <div className=\"grid gap-4 sm:grid-cols-2\">\n          {active === \"deposit\" ? <>\n            <Field label={t.principal} value={principal} onChange={setPrincipal} />\n            <Field label={t.annualRate} value={annualRate} onChange={setAnnualRate} />\n            <Field label={t.days} value={days} onChange={setDays} step=\"1\" />\n            <Field label={t.withholding} value={withholding} onChange={setWithholding} />\n          </> : null}\n          {active === \"compound\" ? <>\n            <Field label={t.principal} value={principal} onChange={setPrincipal} />\n            <Field label={t.annualRate} value={annualRate} onChange={setAnnualRate} />\n            <Field label={t.months} value={months} onChange={setMonths} step=\"1\" />\n            <Field label={t.monthlyContribution} value={monthlyContribution} onChange={setMonthlyContribution} />\n          </> : null}\n          {active === \"goal\" ? <>\n            <Field label={t.principal} value={principal} onChange={setPrincipal} />\n            <Field label={t.target} value={target} onChange={setTarget} />\n            <Field label={t.monthlyContribution} value={monthlyContribution} onChange={setMonthlyContribution} />\n            <Field label={t.annualRate} value={annualRate} onChange={setAnnualRate} />\n          </> : null}\n          {active === \"fx\" ? <>\n            <Field label={t.buyRate} value={buyRate} onChange={setBuyRate} />\n            <Field label={t.sellRate} value={sellRate} onChange={setSellRate} />\n            <Field label={t.quantity} value={quantity} onChange={setQuantity} />\n          </> : null}\n          {active === \"inflation\" ? <>\n            <Field label={t.futureValue} value={futureValue} onChange={setFutureValue} />\n            <Field label={t.inflation} value={inflation} onChange={setInflation} />\n            <Field label={t.years} value={years} onChange={setYears} />\n          </> : null}\n          {active === \"card\" ? <>\n            <Field label={t.balance} value={balance} onChange={setBalance} />\n            <Field label={t.monthlyRate} value={monthlyRate} onChange={setMonthlyRate} />\n          </> : null}\n          {active === \"gold\" ? <>\n            <Field label={t.grams} value={grams} onChange={setGrams} />\n            <Field label={t.buyRate} value={buyRate} onChange={setBuyRate} />\n            <Field label={t.sellRate} value={sellRate} onChange={setSellRate} />\n          </> : null}\n        </div>\n\n        <ResultBox title={t.calculate}>\n          {active === \"deposit\" ? <>\n            <p className=\"flex justify-between gap-4\"><span>{t.gross}</span><strong className=\"text-white\">{money(deposit.gross, locale)}</strong></p>\n            <p className=\"flex justify-between gap-4\"><span>{t.net}</span><strong className=\"text-emerald-300\">{money(deposit.net, locale)}</strong></p>\n            <p className=\"flex justify-between gap-4 border-t border-white/10 pt-2\"><span>{t.final}</span><strong className=\"text-white\">{money(deposit.final, locale)}</strong></p>\n          </> : null}\n          {active === \"compound\" ? <>\n            <p className=\"flex justify-between gap-4\"><span>{t.net}</span><strong className=\"text-emerald-300\">{money(compound.gain, locale)}</strong></p>\n            <p className=\"flex justify-between gap-4 border-t border-white/10 pt-2\"><span>{t.final}</span><strong className=\"text-white\">{money(compound.total, locale)}</strong></p>\n          </> : null}\n          {active === \"goal\" ? <p className=\"text-lg font-black text-white\">{goalMonths === null ? t.unreachable : `${goalMonths} ${t.monthSuffix}`}</p> : null}\n          {active === \"fx\" ? <>\n            <p className=\"flex justify-between gap-4\"><span>{t.cost}</span><strong className=\"text-white\">{money(fxCost, locale)}</strong></p>\n            <p className=\"flex justify-between gap-4\"><span>{t.currentValue}</span><strong className=\"text-white\">{money(fxValue, locale)}</strong></p>\n            <p className=\"flex justify-between gap-4 border-t border-white/10 pt-2\"><span>{t.profit}</span><strong className={fxProfit >= 0 ? \"text-emerald-300\" : \"text-rose-300\"}>{money(fxProfit, locale)}</strong></p>\n          </> : null}\n          {active === \"inflation\" ? <p className=\"flex justify-between gap-4\"><span>{t.realValue}</span><strong className=\"text-white\">{money(purchasingPower, locale)}</strong></p> : null}\n          {active === \"card\" ? <p className=\"flex justify-between gap-4\"><span>{t.estimatedInterest}</span><strong className=\"text-rose-300\">{money(cardInterest, locale)}</strong></p> : null}\n          {active === \"gold\" ? <>\n            <p className=\"flex justify-between gap-4\"><span>{t.cost}</span><strong className=\"text-white\">{money(goldCost, locale)}</strong></p>\n            <p className=\"flex justify-between gap-4\"><span>{t.currentValue}</span><strong className=\"text-white\">{money(goldValue, locale)}</strong></p>\n            <p className=\"flex justify-between gap-4 border-t border-white/10 pt-2\"><span>{t.profit}</span><strong className={goldProfit >= 0 ? \"text-emerald-300\" : \"text-rose-300\"}>{money(goldProfit, locale)}</strong></p>\n          </> : null}\n        </ResultBox>\n      </div>\n      <p className=\"mt-5 rounded-xl border border-amber-300/15 bg-amber-300/[0.06] px-4 py-3 text-xs leading-5 text-amber-100/75\">{t.disclaimer}</p>\n    </section>\n  );\n}\n",
  "components/enhancements/FooterUpgradeLinks.tsx": "\"use client\";\n\nimport Link from \"next/link\";\nimport { usePathname } from \"next/navigation\";\nimport { getLocaleFromPath, localizedHref } from \"@/components/enhancements/locale\";\n\nconst text = {\n  tr: {\n    tools: \"Finans Araçları\",\n    guide: \"Finans Rehberi\",\n    sources: \"Veri Kaynakları\",\n    privacy: \"Gizlilik\",\n    terms: \"Kullanım Şartları\",\n    contact: \"İletişim\"\n  },\n  en: {\n    tools: \"Finance Tools\",\n    guide: \"Finance Guide\",\n    sources: \"Data Sources\",\n    privacy: \"Privacy\",\n    terms: \"Terms\",\n    contact: \"Contact\"\n  },\n  el: {\n    tools: \"Οικονομικά εργαλεία\",\n    guide: \"Οδηγός οικονομικών\",\n    sources: \"Πηγές δεδομένων\",\n    privacy: \"Απόρρητο\",\n    terms: \"Όροι χρήσης\",\n    contact: \"Επικοινωνία\"\n  }\n} as const;\n\nexport function FooterUpgradeLinks() {\n  const pathname = usePathname();\n  const locale = getLocaleFromPath(pathname);\n  const labels = text[locale];\n  const links = [\n    [\"/tools\", labels.tools],\n    [\"/guide\", labels.guide],\n    [\"/data-sources\", labels.sources],\n    [\"/privacy\", labels.privacy],\n    [\"/terms\", labels.terms],\n    [\"/contact\", labels.contact]\n  ] as const;\n\n  return (\n    <nav aria-label=\"Alt bilgi bağlantıları\" className=\"mt-3 flex flex-wrap gap-x-4 gap-y-2 border-t border-white/10 pt-3\">\n      {links.map(([href, label]) => (\n        <Link key={href} href={localizedHref(pathname, href)} className=\"transition hover:text-mint\">\n          {label}\n        </Link>\n      ))}\n      <a\n        href=\"https://instagram.com/boranthegreat\"\n        target=\"_blank\"\n        rel=\"noopener noreferrer\"\n        className=\"transition hover:text-mint\"\n      >\n        Instagram\n      </a>\n    </nav>\n  );\n}\n",
  "components/enhancements/HomeEnhancementPanel.tsx": "\"use client\";\n\nimport Link from \"next/link\";\nimport { usePathname } from \"next/navigation\";\nimport {\n  BellRing,\n  BookOpen,\n  Calculator,\n  Check,\n  CloudSun,\n  Coins,\n  ExternalLink,\n  RefreshCw,\n  Settings2,\n  Share2,\n  Sparkles,\n  TrendingDown,\n  TrendingUp,\n  WalletCards\n} from \"lucide-react\";\nimport { useCallback, useEffect, useMemo, useState } from \"react\";\nimport { getLocaleFromPath, localizedHref, type BtgLocale } from \"@/components/enhancements/locale\";\n\ntype CityKey = \"mersin\" | \"istanbul\" | \"ankara\" | \"athens\" | \"new-york\";\ntype Currency = \"TRY\" | \"USD\" | \"EUR\";\ntype AssetKey = \"usdtry\" | \"bitcoin\" | \"ethereum\" | \"weather\";\n\ntype Preferences = {\n  city: CityKey;\n  currency: Currency;\n  assets: AssetKey[];\n};\n\ntype MarketSnapshot = {\n  usdTry: number | null;\n  usdEur: number | null;\n  btcUsd: number | null;\n  btcTry: number | null;\n  btcChange: number | null;\n  ethUsd: number | null;\n  ethTry: number | null;\n  ethChange: number | null;\n  temperature: number | null;\n  weatherCode: number | null;\n  updatedAt: string | null;\n  errors: string[];\n};\n\nconst DEFAULT_PREFS: Preferences = {\n  city: \"mersin\",\n  currency: \"TRY\",\n  assets: [\"usdtry\", \"bitcoin\", \"ethereum\", \"weather\"]\n};\n\nconst cityOptions: Record<CityKey, { label: Record<BtgLocale, string>; lat: number; lon: number }> = {\n  mersin: { label: { tr: \"Mersin\", en: \"Mersin\", el: \"Μερσίνα\" }, lat: 36.8121, lon: 34.6415 },\n  istanbul: { label: { tr: \"İstanbul\", en: \"Istanbul\", el: \"Κωνσταντινούπολη\" }, lat: 41.0082, lon: 28.9784 },\n  ankara: { label: { tr: \"Ankara\", en: \"Ankara\", el: \"Άγκυρα\" }, lat: 39.9334, lon: 32.8597 },\n  athens: { label: { tr: \"Atina\", en: \"Athens\", el: \"Αθήνα\" }, lat: 37.9838, lon: 23.7275 },\n  \"new-york\": { label: { tr: \"New York\", en: \"New York\", el: \"Νέα Υόρκη\" }, lat: 40.7128, lon: -74.006 }\n};\n\nconst copy = {\n  tr: {\n    eyebrow: \"Kişisel kontrol merkezi\",\n    greeting: \"Tekrar hoş geldin\",\n    title: \"Takip ettiğin veriler, tek bakışta.\",\n    description: \"Ana panel tercihlerini cihazında sakla; piyasayı, hava durumunu ve önemli bağlantıları daha hızlı aç.\",\n    customize: \"Paneli kişiselleştir\",\n    city: \"Varsayılan şehir\",\n    currency: \"Gösterim para birimi\",\n    assets: \"Ana kartlar\",\n    save: \"Tercihleri kaydet\",\n    saved: \"Kaydedildi\",\n    liveTitle: \"Canlı özet\",\n    liveDescription: \"Kaynak ve güncelleme zamanı her kartta açıkça gösterilir.\",\n    refresh: \"Yenile\",\n    loading: \"Canlı veriler hazırlanıyor…\",\n    unavailable: \"Şu anda alınamadı\",\n    updated: \"Güncellendi\",\n    source: \"Kaynak\",\n    dailyTitle: \"Bugünün kısa özeti\",\n    dailyFallback: \"Canlı kaynaklardan yeterli veri alınamadı. Kartları yenileyerek tekrar deneyebilirsin.\",\n    btcUp: \"Bitcoin son 24 saatte yükselişte.\",\n    btcDown: \"Bitcoin son 24 saatte geriliyor.\",\n    btcFlat: \"Bitcoin son 24 saatte yatay seyrediyor.\",\n    usd: \"Dolar/TL anlık olarak\",\n    weather: \"Seçili şehirde sıcaklık\",\n    quickTitle: \"Hızlı işlemler\",\n    tools: \"Finans hesaplamaları\",\n    alerts: \"Kolay alarm oluştur\",\n    portfolio: \"Portföyümü aç\",\n    guide: \"Finans sözlüğü\",\n    share: \"Paylaşım kartı hazırla\",\n    transparent: \"Veri kaynaklarını gör\",\n    weatherCard: \"Hava\",\n    partialData: \"Bazı canlı kaynaklara ulaşılamadı\",\n    assetsLabels: { usdtry: \"USD/TRY\", bitcoin: \"Bitcoin\", ethereum: \"Ethereum\", weather: \"Hava\" }\n  },\n  en: {\n    eyebrow: \"Personal control center\",\n    greeting: \"Welcome back\",\n    title: \"Everything you follow, at a glance.\",\n    description: \"Save dashboard preferences on this device and reach markets, weather and important actions faster.\",\n    customize: \"Customize dashboard\",\n    city: \"Default city\",\n    currency: \"Display currency\",\n    assets: \"Main cards\",\n    save: \"Save preferences\",\n    saved: \"Saved\",\n    liveTitle: \"Live snapshot\",\n    liveDescription: \"Every card clearly shows its source and update time.\",\n    refresh: \"Refresh\",\n    loading: \"Preparing live data…\",\n    unavailable: \"Unavailable right now\",\n    updated: \"Updated\",\n    source: \"Source\",\n    dailyTitle: \"Today in brief\",\n    dailyFallback: \"There is not enough live data right now. Refresh the cards and try again.\",\n    btcUp: \"Bitcoin is up over the last 24 hours.\",\n    btcDown: \"Bitcoin is down over the last 24 hours.\",\n    btcFlat: \"Bitcoin is moving sideways over the last 24 hours.\",\n    usd: \"The live USD/TRY rate is\",\n    weather: \"Temperature in the selected city is\",\n    quickTitle: \"Quick actions\",\n    tools: \"Finance calculators\",\n    alerts: \"Create an easy alert\",\n    portfolio: \"Open my portfolio\",\n    guide: \"Finance glossary\",\n    share: \"Create a share card\",\n    transparent: \"View data sources\",\n    weatherCard: \"Weather\",\n    partialData: \"Some live sources are unavailable\",\n    assetsLabels: { usdtry: \"USD/TRY\", bitcoin: \"Bitcoin\", ethereum: \"Ethereum\", weather: \"Weather\" }\n  },\n  el: {\n    eyebrow: \"Προσωπικό κέντρο ελέγχου\",\n    greeting: \"Καλώς ήρθες ξανά\",\n    title: \"Όσα παρακολουθείς, με μία ματιά.\",\n    description: \"Αποθήκευσε τις προτιμήσεις του πίνακα στη συσκευή και άνοιγε γρηγορότερα αγορές, καιρό και σημαντικές ενέργειες.\",\n    customize: \"Προσαρμογή πίνακα\",\n    city: \"Προεπιλεγμένη πόλη\",\n    currency: \"Νόμισμα εμφάνισης\",\n    assets: \"Κύριες κάρτες\",\n    save: \"Αποθήκευση προτιμήσεων\",\n    saved: \"Αποθηκεύτηκε\",\n    liveTitle: \"Ζωντανή σύνοψη\",\n    liveDescription: \"Κάθε κάρτα εμφανίζει καθαρά την πηγή και την ώρα ενημέρωσης.\",\n    refresh: \"Ανανέωση\",\n    loading: \"Προετοιμασία ζωντανών δεδομένων…\",\n    unavailable: \"Δεν είναι διαθέσιμο τώρα\",\n    updated: \"Ενημερώθηκε\",\n    source: \"Πηγή\",\n    dailyTitle: \"Η ημέρα σε λίγες γραμμές\",\n    dailyFallback: \"Δεν υπάρχουν αρκετά ζωντανά δεδομένα. Κάνε ανανέωση και δοκίμασε ξανά.\",\n    btcUp: \"Το Bitcoin κινείται ανοδικά το τελευταίο 24ωρο.\",\n    btcDown: \"Το Bitcoin υποχωρεί το τελευταίο 24ωρο.\",\n    btcFlat: \"Το Bitcoin κινείται πλευρικά το τελευταίο 24ωρο.\",\n    usd: \"Η ζωντανή ισοτιμία USD/TRY είναι\",\n    weather: \"Η θερμοκρασία στην επιλεγμένη πόλη είναι\",\n    quickTitle: \"Γρήγορες ενέργειες\",\n    tools: \"Οικονομικοί υπολογισμοί\",\n    alerts: \"Εύκολη δημιουργία ειδοποίησης\",\n    portfolio: \"Άνοιγμα χαρτοφυλακίου\",\n    guide: \"Οικονομικό λεξικό\",\n    share: \"Δημιουργία κάρτας κοινοποίησης\",\n    transparent: \"Προβολή πηγών δεδομένων\",\n    weatherCard: \"Καιρός\",\n    partialData: \"Ορισμένες ζωντανές πηγές δεν είναι διαθέσιμες\",\n    assetsLabels: { usdtry: \"USD/TRY\", bitcoin: \"Bitcoin\", ethereum: \"Ethereum\", weather: \"Καιρός\" }\n  }\n} as const;\n\nfunction isHomePath(pathname: string): boolean {\n  return pathname === \"/\" || pathname === \"/tr\" || pathname === \"/en\" || pathname === \"/el\";\n}\n\nfunction formatNumber(value: number | null, locale: BtgLocale, options?: Intl.NumberFormatOptions): string {\n  if (value === null || !Number.isFinite(value)) return \"—\";\n  const localeCode = locale === \"tr\" ? \"tr-TR\" : locale === \"el\" ? \"el-GR\" : \"en-US\";\n  return new Intl.NumberFormat(localeCode, options).format(value);\n}\n\nfunction weatherLabel(code: number | null, locale: BtgLocale): string {\n  if (code === null) return \"\";\n  const labels = {\n    clear: { tr: \"Açık\", en: \"Clear\", el: \"Αίθριος\" },\n    cloudy: { tr: \"Bulutlu\", en: \"Cloudy\", el: \"Συννεφιά\" },\n    fog: { tr: \"Sisli\", en: \"Foggy\", el: \"Ομίχλη\" },\n    rain: { tr: \"Yağmurlu\", en: \"Rainy\", el: \"Βροχή\" },\n    snow: { tr: \"Karlı\", en: \"Snowy\", el: \"Χιόνι\" },\n    storm: { tr: \"Fırtınalı\", en: \"Stormy\", el: \"Καταιγίδα\" }\n  } as const;\n  if (code === 0) return labels.clear[locale];\n  if ([1, 2, 3].includes(code)) return labels.cloudy[locale];\n  if ([45, 48].includes(code)) return labels.fog[locale];\n  if (code >= 51 && code <= 82) return labels.rain[locale];\n  if (code >= 85 && code <= 86) return labels.snow[locale];\n  return labels.storm[locale];\n}\n\nexport function HomeEnhancementPanel() {\n  const pathname = usePathname();\n  const locale = getLocaleFromPath(pathname);\n  const t = copy[locale];\n  const [prefs, setPrefs] = useState<Preferences>(DEFAULT_PREFS);\n  const [draft, setDraft] = useState<Preferences>(DEFAULT_PREFS);\n  const [saved, setSaved] = useState(false);\n  const [loading, setLoading] = useState(true);\n  const [snapshot, setSnapshot] = useState<MarketSnapshot>({\n    usdTry: null,\n    usdEur: null,\n    btcUsd: null,\n    btcTry: null,\n    btcChange: null,\n    ethUsd: null,\n    ethTry: null,\n    ethChange: null,\n    temperature: null,\n    weatherCode: null,\n    updatedAt: null,\n    errors: []\n  });\n\n  useEffect(() => {\n    try {\n      const stored = window.localStorage.getItem(\"btg_dashboard_preferences_v2\");\n      if (!stored) return;\n      const parsed = JSON.parse(stored) as Partial<Preferences>;\n      const next: Preferences = {\n        city: parsed.city && parsed.city in cityOptions ? parsed.city : DEFAULT_PREFS.city,\n        currency: parsed.currency === \"USD\" || parsed.currency === \"EUR\" || parsed.currency === \"TRY\" ? parsed.currency : DEFAULT_PREFS.currency,\n        assets: Array.isArray(parsed.assets)\n          ? parsed.assets.filter((asset): asset is AssetKey => [\"usdtry\", \"bitcoin\", \"ethereum\", \"weather\"].includes(asset))\n          : DEFAULT_PREFS.assets\n      };\n      if (next.assets.length === 0) next.assets = DEFAULT_PREFS.assets;\n      setPrefs(next);\n      setDraft(next);\n    } catch {\n      // Corrupted browser preferences should never block the dashboard.\n    }\n  }, []);\n\n  const loadSnapshot = useCallback(async () => {\n    setLoading(true);\n    const errors: string[] = [];\n    const city = cityOptions[prefs.city];\n    const controller = new AbortController();\n    const timeout = window.setTimeout(() => controller.abort(), 9000);\n\n    try {\n      const [fxResult, cryptoResult, weatherResult] = await Promise.allSettled([\n        fetch(\"https://api.frankfurter.app/latest?from=USD&to=TRY,EUR\", { signal: controller.signal }).then((res) => {\n          if (!res.ok) throw new Error(\"Frankfurter\");\n          return res.json() as Promise<{ rates?: { TRY?: number; EUR?: number } }>;\n        }),\n        fetch(\"https://api.coingecko.com/api/v3/simple/price?ids=bitcoin,ethereum&vs_currencies=usd,try&include_24hr_change=true\", { signal: controller.signal }).then((res) => {\n          if (!res.ok) throw new Error(\"CoinGecko\");\n          return res.json() as Promise<Record<string, Record<string, number>>>;\n        }),\n        fetch(`https://api.open-meteo.com/v1/forecast?latitude=${city.lat}&longitude=${city.lon}&current=temperature_2m,weather_code&timezone=auto`, { signal: controller.signal }).then((res) => {\n          if (!res.ok) throw new Error(\"Open-Meteo\");\n          return res.json() as Promise<{ current?: { temperature_2m?: number; weather_code?: number } }>;\n        })\n      ]);\n\n      const next: MarketSnapshot = {\n        usdTry: null,\n        usdEur: null,\n        btcUsd: null,\n        btcTry: null,\n        btcChange: null,\n        ethUsd: null,\n        ethTry: null,\n        ethChange: null,\n        temperature: null,\n        weatherCode: null,\n        updatedAt: new Date().toISOString(),\n        errors\n      };\n\n      if (fxResult.status === \"fulfilled\") {\n        next.usdTry = fxResult.value.rates?.TRY ?? null;\n        next.usdEur = fxResult.value.rates?.EUR ?? null;\n      } else errors.push(\"Frankfurter\");\n\n      if (cryptoResult.status === \"fulfilled\") {\n        next.btcUsd = cryptoResult.value.bitcoin?.usd ?? null;\n        next.btcTry = cryptoResult.value.bitcoin?.try ?? null;\n        next.btcChange = cryptoResult.value.bitcoin?.usd_24h_change ?? null;\n        next.ethUsd = cryptoResult.value.ethereum?.usd ?? null;\n        next.ethTry = cryptoResult.value.ethereum?.try ?? null;\n        next.ethChange = cryptoResult.value.ethereum?.usd_24h_change ?? null;\n      } else errors.push(\"CoinGecko\");\n\n      if (weatherResult.status === \"fulfilled\") {\n        next.temperature = weatherResult.value.current?.temperature_2m ?? null;\n        next.weatherCode = weatherResult.value.current?.weather_code ?? null;\n      } else errors.push(\"Open-Meteo\");\n\n      setSnapshot({ ...next, errors: [...errors] });\n    } finally {\n      window.clearTimeout(timeout);\n      setLoading(false);\n    }\n  }, [prefs.city]);\n\n  useEffect(() => {\n    if (!isHomePath(pathname)) return;\n    void loadSnapshot();\n  }, [loadSnapshot, pathname]);\n\n  const dailySummary = useMemo(() => {\n    const lines: string[] = [];\n    if (snapshot.btcChange !== null) {\n      if (snapshot.btcChange > 0.35) lines.push(`${t.btcUp} (${formatNumber(snapshot.btcChange, locale, { maximumFractionDigits: 2 })}%)`);\n      else if (snapshot.btcChange < -0.35) lines.push(`${t.btcDown} (${formatNumber(snapshot.btcChange, locale, { maximumFractionDigits: 2 })}%)`);\n      else lines.push(`${t.btcFlat} (${formatNumber(snapshot.btcChange, locale, { maximumFractionDigits: 2 })}%)`);\n    }\n    if (snapshot.usdTry !== null) lines.push(`${t.usd} ${formatNumber(snapshot.usdTry, locale, { minimumFractionDigits: 2, maximumFractionDigits: 4 })}.`);\n    if (snapshot.temperature !== null) lines.push(`${t.weather} ${formatNumber(snapshot.temperature, locale, { maximumFractionDigits: 1 })}°C.`);\n    return lines;\n  }, [locale, snapshot, t]);\n\n  if (!isHomePath(pathname)) return null;\n\n  const savePreferences = () => {\n    const normalized = { ...draft, assets: draft.assets.length ? draft.assets : DEFAULT_PREFS.assets };\n    setPrefs(normalized);\n    try {\n      window.localStorage.setItem(\"btg_dashboard_preferences_v2\", JSON.stringify(normalized));\n    } catch {\n      // Preferences still work for the current session.\n    }\n    setSaved(true);\n    window.setTimeout(() => setSaved(false), 1800);\n  };\n\n  const toggleAsset = (asset: AssetKey) => {\n    setDraft((current) => ({\n      ...current,\n      assets: current.assets.includes(asset) ? current.assets.filter((item) => item !== asset) : [...current.assets, asset]\n    }));\n  };\n\n  const cryptoValue = (usd: number | null, tryValue: number | null) => {\n    if (prefs.currency === \"TRY\") return `${formatNumber(tryValue, locale, { maximumFractionDigits: 0 })} ₺`;\n    if (prefs.currency === \"EUR\") {\n      const eur = usd !== null && snapshot.usdEur !== null ? usd * snapshot.usdEur : null;\n      return `${formatNumber(eur, locale, { maximumFractionDigits: 2 })} €`;\n    }\n    return `$${formatNumber(usd, locale, { maximumFractionDigits: 2 })}`;\n  };\n\n  const cards = [\n    {\n      key: \"usdtry\" as const,\n      title: \"USD/TRY\",\n      value: formatNumber(snapshot.usdTry, locale, { minimumFractionDigits: 2, maximumFractionDigits: 4 }),\n      meta: \"Frankfurter\",\n      icon: Coins,\n      change: null as number | null\n    },\n    {\n      key: \"bitcoin\" as const,\n      title: \"Bitcoin\",\n      value: cryptoValue(snapshot.btcUsd, snapshot.btcTry),\n      meta: \"CoinGecko\",\n      icon: TrendingUp,\n      change: snapshot.btcChange\n    },\n    {\n      key: \"ethereum\" as const,\n      title: \"Ethereum\",\n      value: cryptoValue(snapshot.ethUsd, snapshot.ethTry),\n      meta: \"CoinGecko\",\n      icon: WalletCards,\n      change: snapshot.ethChange\n    },\n    {\n      key: \"weather\" as const,\n      title: `${t.weatherCard} · ${cityOptions[prefs.city].label[locale]}`,\n      value: snapshot.temperature === null ? \"—\" : `${formatNumber(snapshot.temperature, locale, { maximumFractionDigits: 1 })}°C`,\n      meta: `Open-Meteo · ${weatherLabel(snapshot.weatherCode, locale)}`,\n      icon: CloudSun,\n      change: null as number | null\n    }\n  ].filter((card) => prefs.assets.includes(card.key));\n\n  const quickLinks = [\n    { href: \"/tools\", label: t.tools, icon: Calculator },\n    { href: \"/alerts\", label: t.alerts, icon: BellRing },\n    { href: \"/portfolio\", label: t.portfolio, icon: WalletCards },\n    { href: \"/guide\", label: t.guide, icon: BookOpen },\n    { href: \"/tools#share-card\", label: t.share, icon: Share2 },\n    { href: \"/data-sources\", label: t.transparent, icon: ExternalLink }\n  ];\n\n  return (\n    <section className=\"mt-10 space-y-6\" aria-labelledby=\"btg-personal-dashboard-title\">\n      <div className=\"overflow-hidden rounded-3xl border border-mint/20 bg-gradient-to-br from-slate-950/85 via-slate-900/75 to-mint/5 p-6 shadow-card sm:p-8\">\n        <div className=\"flex flex-col gap-6 lg:flex-row lg:items-start lg:justify-between\">\n          <div className=\"max-w-2xl\">\n            <div className=\"inline-flex items-center gap-2 rounded-full border border-mint/20 bg-mint/10 px-3 py-1.5 text-xs font-bold uppercase tracking-[0.2em] text-mint\">\n              <Sparkles className=\"h-3.5 w-3.5\" aria-hidden=\"true\" />\n              {t.eyebrow}\n            </div>\n            <p className=\"mt-5 text-sm font-semibold text-slate-400\">{t.greeting}</p>\n            <h2 id=\"btg-personal-dashboard-title\" className=\"mt-2 text-3xl font-black tracking-tight text-white sm:text-4xl\">{t.title}</h2>\n            <p className=\"mt-3 text-sm leading-7 text-slate-300 sm:text-base\">{t.description}</p>\n          </div>\n\n          <details className=\"w-full rounded-2xl border border-white/10 bg-black/20 p-4 lg:max-w-md\">\n            <summary className=\"flex cursor-pointer list-none items-center justify-between gap-3 font-bold text-white\">\n              <span className=\"inline-flex items-center gap-2\"><Settings2 className=\"h-4 w-4 text-mint\" />{t.customize}</span>\n              <span className=\"text-xs text-slate-400\">▼</span>\n            </summary>\n            <div className=\"mt-5 space-y-4\">\n              <label className=\"block text-sm font-semibold text-slate-300\">\n                {t.city}\n                <select\n                  value={draft.city}\n                  onChange={(event) => setDraft((current) => ({ ...current, city: event.target.value as CityKey }))}\n                  className=\"mt-2 w-full rounded-xl border border-white/10 bg-slate-950 px-3 py-2.5 text-white outline-none focus:border-mint/60\"\n                >\n                  {(Object.keys(cityOptions) as CityKey[]).map((city) => <option key={city} value={city}>{cityOptions[city].label[locale]}</option>)}\n                </select>\n              </label>\n              <label className=\"block text-sm font-semibold text-slate-300\">\n                {t.currency}\n                <select\n                  value={draft.currency}\n                  onChange={(event) => setDraft((current) => ({ ...current, currency: event.target.value as Currency }))}\n                  className=\"mt-2 w-full rounded-xl border border-white/10 bg-slate-950 px-3 py-2.5 text-white outline-none focus:border-mint/60\"\n                >\n                  <option value=\"TRY\">TRY (₺)</option><option value=\"USD\">USD ($)</option><option value=\"EUR\">EUR (€)</option>\n                </select>\n              </label>\n              <fieldset>\n                <legend className=\"text-sm font-semibold text-slate-300\">{t.assets}</legend>\n                <div className=\"mt-2 flex flex-wrap gap-2\">\n                  {(Object.keys(t.assetsLabels) as AssetKey[]).map((asset) => {\n                    const active = draft.assets.includes(asset);\n                    return (\n                      <button\n                        key={asset}\n                        type=\"button\"\n                        onClick={() => toggleAsset(asset)}\n                        className={`inline-flex items-center gap-1.5 rounded-xl border px-3 py-2 text-sm font-semibold transition ${active ? \"border-mint/40 bg-mint/15 text-mint\" : \"border-white/10 bg-white/5 text-slate-400 hover:text-white\"}`}\n                      >\n                        {active ? <Check className=\"h-3.5 w-3.5\" /> : null}{t.assetsLabels[asset]}\n                      </button>\n                    );\n                  })}\n                </div>\n              </fieldset>\n              <button type=\"button\" onClick={savePreferences} className=\"inline-flex w-full items-center justify-center gap-2 rounded-xl bg-mint px-4 py-3 font-black text-slate-950 transition hover:brightness-110\">\n                {saved ? <Check className=\"h-4 w-4\" /> : <Settings2 className=\"h-4 w-4\" />}{saved ? t.saved : t.save}\n              </button>\n            </div>\n          </details>\n        </div>\n      </div>\n\n      <div className=\"rounded-3xl border border-white/10 bg-slate-950/45 p-5 sm:p-6\">\n        <div className=\"flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between\">\n          <div>\n            <h3 className=\"text-xl font-black text-white\">{t.liveTitle}</h3>\n            <p className=\"mt-1 text-sm text-slate-400\">{t.liveDescription}</p>\n          </div>\n          <button type=\"button\" onClick={() => void loadSnapshot()} disabled={loading} className=\"inline-flex items-center justify-center gap-2 rounded-xl border border-white/10 bg-white/5 px-4 py-2 text-sm font-bold text-white transition hover:border-mint/30 hover:text-mint disabled:cursor-wait disabled:opacity-60\">\n            <RefreshCw className={`h-4 w-4 ${loading ? \"animate-spin\" : \"\"}`} />{t.refresh}\n          </button>\n        </div>\n\n        {loading && snapshot.updatedAt === null ? <p className=\"mt-5 text-sm text-slate-400\">{t.loading}</p> : null}\n        {snapshot.errors.length ? <p className=\"mt-4 rounded-xl border border-amber-300/20 bg-amber-300/[0.07] px-3 py-2 text-xs font-semibold text-amber-100\">{t.partialData}: {snapshot.errors.join(\", \")}</p> : null}\n        <div className=\"mt-5 grid gap-4 sm:grid-cols-2 xl:grid-cols-4\">\n          {cards.map((card) => {\n            const Icon = card.icon;\n            const isMissing = card.value === \"—\";\n            return (\n              <article key={card.key} className=\"rounded-2xl border border-white/10 bg-white/[0.035] p-4 transition hover:-translate-y-0.5 hover:border-mint/25\">\n                <div className=\"flex items-start justify-between gap-3\">\n                  <div className=\"rounded-xl border border-mint/15 bg-mint/10 p-2.5 text-mint\"><Icon className=\"h-5 w-5\" /></div>\n                  {card.change !== null ? (\n                    <span className={`inline-flex items-center gap-1 rounded-full px-2 py-1 text-xs font-black ${card.change >= 0 ? \"bg-emerald-400/10 text-emerald-300\" : \"bg-rose-400/10 text-rose-300\"}`}>\n                      {card.change >= 0 ? <TrendingUp className=\"h-3 w-3\" /> : <TrendingDown className=\"h-3 w-3\" />}\n                      {formatNumber(card.change, locale, { maximumFractionDigits: 2 })}%\n                    </span>\n                  ) : null}\n                </div>\n                <p className=\"mt-4 text-sm font-semibold text-slate-400\">{card.title}</p>\n                <p className=\"mt-1 text-2xl font-black text-white\">{isMissing ? t.unavailable : card.value}</p>\n                <div className=\"mt-4 border-t border-white/10 pt-3 text-xs leading-5 text-slate-500\">\n                  <p>{t.source}: {card.meta}</p>\n                  {snapshot.updatedAt ? <p>{t.updated}: {new Date(snapshot.updatedAt).toLocaleTimeString(locale === \"tr\" ? \"tr-TR\" : locale === \"el\" ? \"el-GR\" : \"en-US\", { hour: \"2-digit\", minute: \"2-digit\" })}</p> : null}\n                </div>\n              </article>\n            );\n          })}\n        </div>\n      </div>\n\n      <div className=\"grid gap-6 lg:grid-cols-[1.2fr_1fr]\">\n        <article className=\"rounded-3xl border border-white/10 bg-slate-950/45 p-6\">\n          <div className=\"flex items-center gap-2 text-mint\"><Sparkles className=\"h-5 w-5\" /><h3 className=\"text-xl font-black text-white\">{t.dailyTitle}</h3></div>\n          <div className=\"mt-4 space-y-3 text-sm leading-7 text-slate-300\">\n            {dailySummary.length ? dailySummary.map((line) => <p key={line}>{line}</p>) : <p>{t.dailyFallback}</p>}\n          </div>\n        </article>\n\n        <article className=\"rounded-3xl border border-white/10 bg-slate-950/45 p-6\">\n          <h3 className=\"text-xl font-black text-white\">{t.quickTitle}</h3>\n          <div className=\"mt-4 grid gap-2 sm:grid-cols-2 lg:grid-cols-1 xl:grid-cols-2\">\n            {quickLinks.map(({ href, label, icon: Icon }) => (\n              <Link key={href} href={localizedHref(pathname, href)} className=\"group flex items-center gap-3 rounded-2xl border border-white/10 bg-white/[0.035] p-3 text-sm font-bold text-slate-300 transition hover:border-mint/30 hover:text-mint\">\n                <span className=\"rounded-xl bg-white/5 p-2 transition group-hover:bg-mint/10\"><Icon className=\"h-4 w-4\" /></span>{label}\n              </Link>\n            ))}\n          </div>\n        </article>\n      </div>\n    </section>\n  );\n}\n",
  "components/enhancements/LocalizedBrandLink.tsx": "\"use client\";\n\nimport Link from \"next/link\";\nimport { usePathname } from \"next/navigation\";\nimport type { ReactNode } from \"react\";\nimport { localizedHref } from \"@/components/enhancements/locale\";\n\nexport function LocalizedBrandLink({ children, className }: { children: ReactNode; className?: string }) {\n  const pathname = usePathname();\n  return (\n    <Link href={localizedHref(pathname, \"/\")} aria-label=\"BoranTheGreat ana sayfasına dön\" className={className}>\n      {children}\n    </Link>\n  );\n}\n",
  "components/enhancements/MobileBottomNavigation.tsx": "\"use client\";\n\nimport Link from \"next/link\";\nimport { usePathname } from \"next/navigation\";\nimport { BellRing, Calculator, CircleDollarSign, House, WalletCards } from \"lucide-react\";\nimport { getLocaleFromPath, localizedHref } from \"@/components/enhancements/locale\";\n\nconst labels = {\n  tr: { home: \"Panel\", markets: \"Piyasa\", portfolio: \"Portföy\", alerts: \"Alarm\", tools: \"Araçlar\" },\n  en: { home: \"Home\", markets: \"Markets\", portfolio: \"Portfolio\", alerts: \"Alerts\", tools: \"Tools\" },\n  el: { home: \"Αρχική\", markets: \"Αγορές\", portfolio: \"Χαρτοφυλάκιο\", alerts: \"Ειδοπ.\", tools: \"Εργαλεία\" }\n} as const;\n\nexport function MobileBottomNavigation() {\n  const pathname = usePathname();\n  const locale = getLocaleFromPath(pathname);\n  const t = labels[locale];\n  const links = [\n    { href: \"/\", label: t.home, icon: House },\n    { href: \"/exchange\", label: t.markets, icon: CircleDollarSign },\n    { href: \"/portfolio\", label: t.portfolio, icon: WalletCards },\n    { href: \"/alerts\", label: t.alerts, icon: BellRing },\n    { href: \"/tools\", label: t.tools, icon: Calculator }\n  ];\n\n  return (\n    <nav aria-label=\"Mobil ana menü\" className=\"btg-mobile-nav fixed inset-x-3 bottom-3 z-50 grid grid-cols-5 rounded-2xl border border-white/10 bg-slate-950/90 p-1.5 shadow-2xl backdrop-blur-xl md:hidden\">\n      {links.map(({ href, label, icon: Icon }) => {\n        const localized = localizedHref(pathname, href);\n        const active = href === \"/\" ? pathname === `/${locale}` || pathname === \"/\" : pathname.startsWith(localized);\n        return (\n          <Link key={href} href={localized} aria-current={active ? \"page\" : undefined} className={`flex min-h-12 flex-col items-center justify-center gap-1 rounded-xl px-1 text-[10px] font-bold transition ${active ? \"bg-mint/15 text-mint\" : \"text-slate-400 hover:text-white\"}`}>\n            <Icon className=\"h-4 w-4\" aria-hidden=\"true\" />\n            <span>{label}</span>\n          </Link>\n        );\n      })}\n    </nav>\n  );\n}\n",
  "components/enhancements/PageHero.tsx": "import type { ReactNode } from \"react\";\n\nexport function PageHero({ eyebrow, title, description, children }: {\n  eyebrow: string;\n  title: string;\n  description: string;\n  children?: ReactNode;\n}) {\n  return (\n    <section className=\"relative overflow-hidden rounded-3xl border border-white/10 bg-slate-950/55 p-6 shadow-card sm:p-8\">\n      <div className=\"pointer-events-none absolute -right-20 -top-24 h-64 w-64 rounded-full bg-mint/10 blur-3xl\" />\n      <div className=\"relative max-w-3xl\">\n        <p className=\"text-xs font-bold uppercase tracking-[0.24em] text-mint\">{eyebrow}</p>\n        <h1 className=\"mt-3 text-3xl font-black tracking-tight text-white sm:text-5xl\">{title}</h1>\n        <p className=\"mt-4 max-w-2xl text-sm leading-7 text-slate-300 sm:text-base\">{description}</p>\n        {children ? <div className=\"mt-6\">{children}</div> : null}\n      </div>\n    </section>\n  );\n}\n",
  "components/enhancements/QuickToolsButton.tsx": "\"use client\";\n\nimport Link from \"next/link\";\nimport { Calculator } from \"lucide-react\";\nimport { usePathname } from \"next/navigation\";\nimport { getLocaleFromPath, localizedHref } from \"@/components/enhancements/locale\";\n\nconst labels = {\n  tr: \"Araçlar\",\n  en: \"Tools\",\n  el: \"Εργαλεία\"\n} as const;\n\nexport function QuickToolsButton() {\n  const pathname = usePathname();\n  const locale = getLocaleFromPath(pathname);\n\n  return (\n    <Link\n      href={localizedHref(pathname, \"/tools\")}\n      className=\"inline-flex min-h-10 items-center gap-2 rounded-xl border border-mint/25 bg-mint/10 px-3 py-2 text-sm font-semibold text-mint transition hover:border-mint/50 hover:bg-mint/15\"\n    >\n      <Calculator className=\"h-4 w-4\" aria-hidden=\"true\" />\n      <span>{labels[locale]}</span>\n    </Link>\n  );\n}\n",
  "components/enhancements/ShareCardGenerator.tsx": "\"use client\";\n\nimport { usePathname } from \"next/navigation\";\nimport { Download, Image as ImageIcon, Share2 } from \"lucide-react\";\nimport { useRef, useState } from \"react\";\nimport { getLocaleFromPath } from \"@/components/enhancements/locale\";\n\nconst copy = {\n  tr: {\n    title: \"Paylaşılabilir Piyasa Kartı\",\n    description: \"Bir fiyat ve değişim değeri gir; Instagram hikâyesi veya X paylaşımı için markalı PNG oluştur.\",\n    asset: \"Varlık adı\",\n    price: \"Fiyat\",\n    change: \"Değişim (%)\",\n    note: \"Kısa not\",\n    notePlaceholder: \"Piyasa takibim\",\n    generate: \"Kartı oluştur\",\n    download: \"PNG indir\",\n    preview: \"Önizleme\",\n    disclaimer: \"Bilgilendirme amaçlıdır · Yatırım tavsiyesi değildir\"\n  },\n  en: {\n    title: \"Shareable Market Card\",\n    description: \"Enter a price and change value to create a branded PNG for Instagram Stories or X.\",\n    asset: \"Asset name\",\n    price: \"Price\",\n    change: \"Change (%)\",\n    note: \"Short note\",\n    notePlaceholder: \"My market watch\",\n    generate: \"Generate card\",\n    download: \"Download PNG\",\n    preview: \"Preview\",\n    disclaimer: \"For information only · Not investment advice\"\n  },\n  el: {\n    title: \"Κάρτα αγοράς για κοινοποίηση\",\n    description: \"Βάλε τιμή και ποσοστό μεταβολής για να δημιουργήσεις επώνυμο PNG για Instagram Stories ή X.\",\n    asset: \"Όνομα στοιχείου\",\n    price: \"Τιμή\",\n    change: \"Μεταβολή (%)\",\n    note: \"Σύντομη σημείωση\",\n    notePlaceholder: \"Η παρακολούθηση αγοράς μου\",\n    generate: \"Δημιουργία κάρτας\",\n    download: \"Λήψη PNG\",\n    preview: \"Προεπισκόπηση\",\n    disclaimer: \"Μόνο για ενημέρωση · Δεν αποτελεί επενδυτική συμβουλή\"\n  }\n} as const;\n\nexport function ShareCardGenerator() {\n  const pathname = usePathname();\n  const locale = getLocaleFromPath(pathname);\n  const t = copy[locale];\n  const canvasRef = useRef<HTMLCanvasElement>(null);\n  const [asset, setAsset] = useState(\"Bitcoin\");\n  const [price, setPrice] = useState(\"$118,240\");\n  const [change, setChange] = useState(2.8);\n  const [note, setNote] = useState(\"\");\n  const [ready, setReady] = useState(false);\n\n  const drawCard = () => {\n    const canvas = canvasRef.current;\n    if (!canvas) return;\n    const context = canvas.getContext(\"2d\");\n    if (!context) return;\n\n    const width = 1080;\n    const height = 1350;\n    canvas.width = width;\n    canvas.height = height;\n\n    const gradient = context.createLinearGradient(0, 0, width, height);\n    gradient.addColorStop(0, \"#07111f\");\n    gradient.addColorStop(0.55, \"#0f172a\");\n    gradient.addColorStop(1, \"#022c22\");\n    context.fillStyle = gradient;\n    context.fillRect(0, 0, width, height);\n\n    context.globalAlpha = 0.24;\n    context.fillStyle = \"#5eead4\";\n    context.beginPath();\n    context.arc(900, 150, 300, 0, Math.PI * 2);\n    context.fill();\n    context.globalAlpha = 1;\n\n    context.strokeStyle = \"rgba(94,234,212,0.22)\";\n    context.lineWidth = 2;\n    for (let x = 80; x < width; x += 80) {\n      context.beginPath(); context.moveTo(x, 0); context.lineTo(x, height); context.stroke();\n    }\n    for (let y = 80; y < height; y += 80) {\n      context.beginPath(); context.moveTo(0, y); context.lineTo(width, y); context.stroke();\n    }\n\n    context.fillStyle = \"#5eead4\";\n    context.font = \"700 34px Arial\";\n    context.fillText(\"BORANTHEGREAT.XYZ\", 90, 115);\n\n    context.fillStyle = \"rgba(255,255,255,0.68)\";\n    context.font = \"600 25px Arial\";\n    context.fillText(new Date().toLocaleDateString(locale === \"tr\" ? \"tr-TR\" : locale === \"el\" ? \"el-GR\" : \"en-US\"), 90, 170);\n\n    context.fillStyle = \"#ffffff\";\n    context.font = \"900 78px Arial\";\n    context.fillText(asset.slice(0, 20), 90, 490);\n\n    context.font = \"900 116px Arial\";\n    context.fillText(price.slice(0, 18), 90, 650);\n\n    const changeText = `${change >= 0 ? \"+\" : \"\"}${change.toFixed(2)}%`;\n    context.fillStyle = change >= 0 ? \"#6ee7b7\" : \"#fda4af\";\n    context.font = \"900 64px Arial\";\n    context.fillText(changeText, 90, 760);\n\n    context.fillStyle = \"rgba(255,255,255,0.82)\";\n    context.font = \"500 32px Arial\";\n    context.fillText((note || t.notePlaceholder).slice(0, 45), 90, 890);\n\n    context.strokeStyle = \"rgba(255,255,255,0.14)\";\n    context.beginPath(); context.moveTo(90, 1050); context.lineTo(990, 1050); context.stroke();\n\n    context.fillStyle = \"rgba(255,255,255,0.62)\";\n    context.font = \"500 24px Arial\";\n    context.fillText(t.disclaimer, 90, 1120);\n    context.fillStyle = \"#5eead4\";\n    context.font = \"800 30px Arial\";\n    context.fillText(\"boranthegreat.xyz\", 90, 1210);\n\n    setReady(true);\n  };\n\n  const download = () => {\n    const canvas = canvasRef.current;\n    if (!canvas) return;\n    if (!ready) drawCard();\n    window.setTimeout(() => {\n      const link = document.createElement(\"a\");\n      link.download = `boranthegreat-${asset.toLowerCase().replace(/[^a-z0-9]+/g, \"-\") || \"market\"}.png`;\n      link.href = canvas.toDataURL(\"image/png\");\n      link.click();\n    }, 0);\n  };\n\n  return (\n    <section id=\"share-card\" className=\"scroll-mt-28 rounded-3xl border border-white/10 bg-slate-950/45 p-5 shadow-card sm:p-7\">\n      <div className=\"flex items-start gap-3\">\n        <span className=\"rounded-2xl border border-mint/20 bg-mint/10 p-3 text-mint\"><Share2 className=\"h-6 w-6\" /></span>\n        <div>\n          <h2 className=\"text-2xl font-black text-white\">{t.title}</h2>\n          <p className=\"mt-2 text-sm leading-7 text-slate-400\">{t.description}</p>\n        </div>\n      </div>\n\n      <div className=\"mt-6 grid gap-6 lg:grid-cols-[0.8fr_1.2fr]\">\n        <div className=\"grid content-start gap-4 sm:grid-cols-2 lg:grid-cols-1\">\n          <label className=\"text-sm font-semibold text-slate-300\">{t.asset}<input value={asset} onChange={(event) => { setAsset(event.target.value); setReady(false); }} className=\"mt-2 w-full rounded-xl border border-white/10 bg-slate-950 px-3 py-3 text-white outline-none focus:border-mint/60\" /></label>\n          <label className=\"text-sm font-semibold text-slate-300\">{t.price}<input value={price} onChange={(event) => { setPrice(event.target.value); setReady(false); }} className=\"mt-2 w-full rounded-xl border border-white/10 bg-slate-950 px-3 py-3 text-white outline-none focus:border-mint/60\" /></label>\n          <label className=\"text-sm font-semibold text-slate-300\">{t.change}<input type=\"number\" step=\"any\" value={change} onChange={(event) => { setChange(Number(event.target.value)); setReady(false); }} className=\"mt-2 w-full rounded-xl border border-white/10 bg-slate-950 px-3 py-3 text-white outline-none focus:border-mint/60\" /></label>\n          <label className=\"text-sm font-semibold text-slate-300\">{t.note}<input value={note} onChange={(event) => { setNote(event.target.value); setReady(false); }} placeholder={t.notePlaceholder} className=\"mt-2 w-full rounded-xl border border-white/10 bg-slate-950 px-3 py-3 text-white outline-none placeholder:text-slate-600 focus:border-mint/60\" /></label>\n          <div className=\"flex flex-col gap-2 sm:col-span-2 lg:col-span-1 sm:flex-row lg:flex-col xl:flex-row\">\n            <button type=\"button\" onClick={drawCard} className=\"inline-flex flex-1 items-center justify-center gap-2 rounded-xl bg-mint px-4 py-3 font-black text-slate-950 transition hover:brightness-110\"><ImageIcon className=\"h-4 w-4\" />{t.generate}</button>\n            <button type=\"button\" onClick={download} className=\"inline-flex flex-1 items-center justify-center gap-2 rounded-xl border border-white/10 bg-white/5 px-4 py-3 font-bold text-white transition hover:border-mint/30 hover:text-mint\"><Download className=\"h-4 w-4\" />{t.download}</button>\n          </div>\n        </div>\n\n        <div>\n          <p className=\"mb-2 text-xs font-black uppercase tracking-[0.18em] text-slate-500\">{t.preview}</p>\n          <div className=\"overflow-hidden rounded-2xl border border-white/10 bg-black/20 p-2\">\n            <canvas ref={canvasRef} aria-label={t.preview} className=\"aspect-[4/5] w-full rounded-xl bg-slate-950\" />\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n}\n",
  "components/enhancements/StaticInfoPage.tsx": "\"use client\";\n\nimport Link from \"next/link\";\nimport { usePathname } from \"next/navigation\";\nimport { Database, ExternalLink, ShieldCheck } from \"lucide-react\";\nimport { getLocaleFromPath, localizedHref, type BtgLocale } from \"@/components/enhancements/locale\";\nimport { PageHero } from \"@/components/enhancements/PageHero\";\nimport { DataPrivacyControls } from \"@/components/enhancements/DataPrivacyControls\";\n\nexport type InfoKind = \"privacy\" | \"terms\" | \"sources\" | \"contact\" | \"guide\";\n\ntype Section = { title: string; paragraphs?: string[]; bullets?: string[] };\ntype Content = { eyebrow: string; title: string; description: string; sections: Section[] };\n\nconst content: Record<BtgLocale, Record<InfoKind, Content>> = {\n  tr: {\n    privacy: {\n      eyebrow: \"Şeffaflık\",\n      title: \"Gizlilik Politikası\",\n      description: \"BoranTheGreat'in hangi verileri cihazda sakladığını, isteğe bağlı bulut özelliklerini ve verilerini nasıl temizleyebileceğini açıklar.\",\n      sections: [\n        { title: \"Cihazda saklanan veriler\", paragraphs: [\"Favoriler, portföy, alarm taslakları, tema, dil, şehir ve panel tercihleri tarayıcının LocalStorage alanında saklanabilir. Bu veriler varsayılan olarak cihazından ayrılmaz.\"] },\n        { title: \"İsteğe bağlı bulut hesabı\", paragraphs: [\"Google ile giriş ve Supabase yapılandırıldığında seçtiğin veriler cihazlar arasında eşitlenebilir. Bulut özelliği kurulmamışsa veya giriş yapmazsan yerel kullanım devam eder.\"] },\n        { title: \"Dış veri sağlayıcıları\", paragraphs: [\"Piyasa, haber ve hava verisi alınırken üçüncü taraf API sağlayıcılarına ağ isteği gönderilir. Bu sağlayıcılar kendi gizlilik politikalarına göre IP adresi ve teknik istek bilgilerini işleyebilir.\"] },\n        { title: \"Çerezler ve tarayıcı depolaması\", paragraphs: [\"Dil tercihi ve oturum gibi gerekli işlevler için çerez veya tarayıcı depolaması kullanılabilir. Reklam amaçlı takip çerezi bu sürümün temel işlevi değildir.\"] },\n        { title: \"Verilerini silme\", bullets: [\"Ayarlar veya ilgili ekranlardan yerel verileri temizle.\", \"Tarayıcının site verilerini silme seçeneğini kullan.\", \"Bulut hesabı etkinse hesabından çıkış yap ve senkronize verilerin silinmesi için iletişim kanalını kullan.\"] },\n        { title: \"Güncellemeler\", paragraphs: [\"Özellikler değiştiğinde bu politika güncellenebilir. Önemli değişiklikler bu sayfada yayımlanır.\"] }\n      ]\n    },\n    terms: {\n      eyebrow: \"Kullanım çerçevesi\",\n      title: \"Kullanım Şartları\",\n      description: \"Siteyi kullanırken geçerli olan temel koşullar ve finansal veri sorumluluk sınırları.\",\n      sections: [\n        { title: \"Bilgilendirme hizmeti\", paragraphs: [\"BoranTheGreat piyasa, hava, haber, portföy ve hesaplama araçlarını bilgilendirme amacıyla sunar.\"] },\n        { title: \"Yatırım tavsiyesi değildir\", paragraphs: [\"Sitedeki fiyatlar, özetler, hesaplamalar, BorAI yanıtları ve alarmlar yatırım, kredi, vergi veya hukuk tavsiyesi değildir. Finansal kararların sorumluluğu kullanıcıya aittir.\"] },\n        { title: \"Veri doğruluğu ve gecikme\", paragraphs: [\"Üçüncü taraf sağlayıcılardan gelen veriler gecikebilir, eksik olabilir veya geçici olarak kullanılamayabilir. İşlem yapmadan önce resmi ve yetkili kaynaklardan doğrulama yapmalısın.\"] },\n        { title: \"Kullanıcı sorumluluğu\", bullets: [\"Hesap ve cihaz güvenliğini korumak.\", \"Alarm ve hesaplama sonuçlarını bağımsız olarak kontrol etmek.\", \"Siteyi hukuka aykırı, yanıltıcı veya sistemi zorlayıcı biçimde kullanmamak.\"] },\n        { title: \"Hizmet sürekliliği\", paragraphs: [\"Bakım, API sınırları, bağlantı sorunları veya teknik arızalar nedeniyle özellikler geçici olarak kesilebilir. Kesintisiz erişim garantisi verilmez.\"] },\n        { title: \"Değişiklikler\", paragraphs: [\"Bu şartlar özellik ve mevzuat değişikliklerine göre güncellenebilir. Siteyi kullanmaya devam etmek güncel şartların kabul edildiği anlamına gelir.\"] }\n      ]\n    },\n    sources: {\n      eyebrow: \"Veri güveni\",\n      title: \"Veri Kaynakları ve Güncellik\",\n      description: \"Kartlarda gördüğün fiyatların, hava verilerinin ve haberlerin hangi sağlayıcılardan geldiğini gösterir.\",\n      sections: [\n        { title: \"Döviz\", bullets: [\"Frankfurter API: temel döviz kurları ve tarihsel seriler.\", \"Kartlarda mümkün olduğunda son güncelleme zamanı gösterilir.\"] },\n        { title: \"Kripto\", bullets: [\"CoinGecko: fiyat, değişim, hacim, piyasa değeri ve grafik verileri.\", \"CoinLore: CoinGecko erişilemediğinde bazı ekranlarda yedek veri.\"] },\n        { title: \"Altın\", bullets: [\"Yahoo Finance veya projedeki sunucu katmanı: yaklaşık ons verisi.\", \"Gram altın hesaplaması kur ve ons verisinden türetilebilir; kuyumcu alış/satış fiyatıyla birebir aynı olmayabilir.\"] },\n        { title: \"Hava\", bullets: [\"Open-Meteo Geocoding: şehir arama.\", \"Open-Meteo Forecast: anlık durum ve tahmin.\"] },\n        { title: \"Haber ve takvim\", bullets: [\"GDELT: dil ve kategori bazlı haber akışı.\", \"Finnhub: API anahtarı eklendiğinde ekonomi takvimi.\"] },\n        { title: \"Yapay zekâ\", bullets: [\"OpenAI: anahtar eklendiğinde BorAI'nin bulut yanıt modu.\", \"Anahtar yoksa proje yerel yardımcı metinlerle çalışabilir.\"] },\n        { title: \"Gecikme ve hata politikası\", paragraphs: [\"Kaynak erişilemezse sahte canlı veri gösterilmemeli; son bilinen değer, hata durumu veya yedek kaynak açık biçimde belirtilmelidir.\"] }\n      ]\n    },\n    contact: {\n      eyebrow: \"İletişim\",\n      title: \"BoranTheGreat'e Ulaş\",\n      description: \"Hata bildirimi, özellik önerisi veya veri kaynağı geri bildirimi için resmi sosyal kanal.\",\n      sections: [\n        { title: \"Instagram\", paragraphs: [\"Mesajında kullandığın cihazı, sayfanın adresini ve gördüğün sorunu mümkün olduğunca net belirt. Ekran görüntüsü eklemek çözümü hızlandırır.\"] },\n        { title: \"Hata bildirirken\", bullets: [\"Sorunun oluştuğu sayfa adresi.\", \"Telefon veya bilgisayar ve tarayıcı adı.\", \"Sorunun yaklaşık zamanı.\", \"Kişisel veya gizli bilgi içermeyen ekran görüntüsü.\"] }\n      ]\n    },\n    guide: {\n      eyebrow: \"Öğrenme merkezi\",\n      title: \"Finans Rehberi ve Sözlük\",\n      description: \"Piyasa ekranlarında geçen temel kavramları kısa ve anlaşılır biçimde açıklar.\",\n      sections: [\n        { title: \"Stopaj\", paragraphs: [\"Faiz veya yatırım gelirinden yasal olarak kesilen vergidir. Net kazanç, brüt kazançtan stopaj düşüldükten sonra kalan tutardır.\"] },\n        { title: \"Piyasa değeri\", paragraphs: [\"Bir varlığın dolaşımdaki adedi ile güncel fiyatının çarpımıdır. Tek başına ucuzluk veya pahalılık göstergesi değildir.\"] },\n        { title: \"Hacim\", paragraphs: [\"Belirli sürede gerçekleşen işlem büyüklüğüdür. Yüksek hacim genellikle daha fazla işlem ilgisine işaret eder.\"] },\n        { title: \"Alış–satış farkı\", paragraphs: [\"Bir varlığı alabileceğin fiyat ile satabileceğin fiyat arasındaki farktır. Bu fark işlem maliyetinin bir parçasıdır.\"] },\n        { title: \"Volatilite\", paragraphs: [\"Fiyatın ne kadar hızlı ve geniş aralıkta değiştiğini anlatır. Yüksek volatilite daha yüksek risk anlamına gelebilir.\"] },\n        { title: \"Portföy çeşitlendirmesi\", paragraphs: [\"Tüm birikimi tek varlığa bağlamak yerine farklı risklere dağıtmaktır. Çeşitlendirme zararı tamamen engellemez.\"] },\n        { title: \"Fiyat alarmı\", paragraphs: [\"Belirlediğin fiyat koşulu gerçekleştiğinde kontrol veya bildirim sağlayan araçtır. Alarm, emrin otomatik gerçekleştiği anlamına gelmez.\"] },\n        { title: \"Güvenli kullanım\", bullets: [\"Tek bir veri kaynağına güvenme.\", \"Yüksek getiri vaadini yüksek riskten ayrı düşünme.\", \"Krediyle veya acil ihtiyaç parasıyla riskli işlem yapmadan önce profesyonel görüş al.\"] }\n      ]\n    }\n  },\n  en: {\n    privacy: { eyebrow: \"Transparency\", title: \"Privacy Policy\", description: \"Explains what BoranTheGreat stores on your device, optional cloud features and how to clear your data.\", sections: [\n      { title: \"Data stored on your device\", paragraphs: [\"Favorites, portfolio items, alert drafts, theme, language, city and dashboard preferences may be stored in browser LocalStorage. By default, this data does not leave your device.\"] },\n      { title: \"Optional cloud account\", paragraphs: [\"When Google sign-in and Supabase are configured, selected data may sync across devices. Local use continues when cloud services are not configured or you do not sign in.\"] },\n      { title: \"External data providers\", paragraphs: [\"Network requests are sent to third-party APIs for market, news and weather data. Those providers may process IP addresses and technical request information under their own policies.\"] },\n      { title: \"Cookies and browser storage\", paragraphs: [\"Cookies or browser storage may be used for necessary functions such as language and sessions. Advertising tracking is not a core function of this version.\"] },\n      { title: \"Deleting your data\", bullets: [\"Clear local data from settings or the related screen.\", \"Delete site data in your browser.\", \"When cloud sync is enabled, sign out and use the contact channel to request deletion of synchronized data.\"] },\n      { title: \"Updates\", paragraphs: [\"This policy may be updated when features change. Important changes will be published on this page.\"] }\n    ] },\n    terms: { eyebrow: \"Usage framework\", title: \"Terms of Use\", description: \"Core conditions for using the site and the limits of responsibility for financial data.\", sections: [\n      { title: \"Information service\", paragraphs: [\"BoranTheGreat provides market, weather, news, portfolio and calculator tools for information purposes.\"] },\n      { title: \"Not financial advice\", paragraphs: [\"Prices, summaries, calculations, BorAI answers and alerts are not investment, credit, tax or legal advice. Users are responsible for their decisions.\"] },\n      { title: \"Accuracy and delay\", paragraphs: [\"Third-party data may be delayed, incomplete or temporarily unavailable. Verify important information with official sources before acting.\"] },\n      { title: \"User responsibility\", bullets: [\"Protect account and device security.\", \"Independently verify alert and calculation results.\", \"Do not use the service unlawfully or in ways that overload the system.\"] },\n      { title: \"Availability\", paragraphs: [\"Features may be interrupted by maintenance, API limits, network issues or technical faults. Continuous access is not guaranteed.\"] },\n      { title: \"Changes\", paragraphs: [\"Terms may change with features or regulation. Continued use means acceptance of the current terms.\"] }\n    ] },\n    sources: { eyebrow: \"Data trust\", title: \"Data Sources and Freshness\", description: \"Shows where prices, weather data and news come from.\", sections: [\n      { title: \"Foreign exchange\", bullets: [\"Frankfurter API for core rates and historical series.\", \"Cards show an update time whenever possible.\"] },\n      { title: \"Crypto\", bullets: [\"CoinGecko for prices, changes, volume, market cap and charts.\", \"CoinLore as a fallback on selected screens.\"] },\n      { title: \"Gold\", bullets: [\"Yahoo Finance or the project server layer for approximate ounce data.\", \"Gram gold can be derived from FX and ounce values and may differ from retail quotes.\"] },\n      { title: \"Weather\", bullets: [\"Open-Meteo Geocoding for city search.\", \"Open-Meteo Forecast for current conditions and forecasts.\"] },\n      { title: \"News and calendar\", bullets: [\"GDELT for language and category-based news.\", \"Finnhub for the economic calendar when a key is configured.\"] },\n      { title: \"Artificial intelligence\", bullets: [\"OpenAI for BorAI cloud responses when a key is configured.\", \"The project may use local helper responses without a key.\"] },\n      { title: \"Failure policy\", paragraphs: [\"When a source is unavailable, the site should show a clear error, last known value or labeled fallback—not fabricated live data.\"] }\n    ] },\n    contact: { eyebrow: \"Contact\", title: \"Contact BoranTheGreat\", description: \"Use the official social channel for bug reports, feature ideas or data feedback.\", sections: [\n      { title: \"Instagram\", paragraphs: [\"Include the device, page address and a clear description. A screenshot without private information can speed up diagnosis.\"] },\n      { title: \"For bug reports\", bullets: [\"Affected page URL.\", \"Device and browser.\", \"Approximate time.\", \"Screenshot without personal or secret data.\"] }\n    ] },\n    guide: { eyebrow: \"Learning center\", title: \"Finance Guide and Glossary\", description: \"Short explanations of common terms used on market screens.\", sections: [\n      { title: \"Withholding tax\", paragraphs: [\"Tax withheld from interest or investment income. Net return is what remains after withholding is deducted from gross return.\"] },\n      { title: \"Market capitalization\", paragraphs: [\"Circulating supply multiplied by current price. It does not by itself prove that an asset is cheap or expensive.\"] },\n      { title: \"Volume\", paragraphs: [\"The amount traded over a period. Higher volume often indicates greater trading activity.\"] },\n      { title: \"Bid–ask spread\", paragraphs: [\"The difference between a buying and selling quote. It is part of transaction cost.\"] },\n      { title: \"Volatility\", paragraphs: [\"How quickly and widely price changes. Higher volatility can mean higher risk.\"] },\n      { title: \"Diversification\", paragraphs: [\"Spreading savings across different risks rather than relying on one asset. It cannot eliminate losses.\"] },\n      { title: \"Price alert\", paragraphs: [\"A tool that checks or notifies when a price condition is met. It does not execute a trade automatically.\"] },\n      { title: \"Safer use\", bullets: [\"Do not rely on one source.\", \"Consider risk together with return.\", \"Seek professional advice before using borrowed or essential money for risky activity.\"] }\n    ] }\n  },\n  el: {\n    privacy: { eyebrow: \"Διαφάνεια\", title: \"Πολιτική απορρήτου\", description: \"Εξηγεί τι αποθηκεύεται στη συσκευή, τις προαιρετικές λειτουργίες cloud και τον τρόπο διαγραφής δεδομένων.\", sections: [\n      { title: \"Δεδομένα στη συσκευή\", paragraphs: [\"Αγαπημένα, χαρτοφυλάκιο, προσχέδια ειδοποιήσεων, θέμα, γλώσσα, πόλη και προτιμήσεις μπορούν να αποθηκεύονται στο LocalStorage. Από προεπιλογή δεν εγκαταλείπουν τη συσκευή.\"] },\n      { title: \"Προαιρετικός λογαριασμός cloud\", paragraphs: [\"Με Google και Supabase, επιλεγμένα δεδομένα μπορούν να συγχρονιστούν. Χωρίς ρύθμιση ή σύνδεση, η τοπική χρήση συνεχίζεται.\"] },\n      { title: \"Εξωτερικοί πάροχοι\", paragraphs: [\"Για αγορές, ειδήσεις και καιρό γίνονται αιτήματα σε τρίτα API, τα οποία μπορεί να επεξεργάζονται IP και τεχνικά στοιχεία σύμφωνα με τις πολιτικές τους.\"] },\n      { title: \"Cookies και αποθήκευση\", paragraphs: [\"Μπορεί να χρησιμοποιούνται για απαραίτητες λειτουργίες όπως γλώσσα και συνεδρία. Η διαφημιστική παρακολούθηση δεν είναι βασική λειτουργία αυτής της έκδοσης.\"] },\n      { title: \"Διαγραφή δεδομένων\", bullets: [\"Καθάρισε τοπικά δεδομένα από τις ρυθμίσεις.\", \"Διέγραψε τα δεδομένα ιστοτόπου από τον browser.\", \"Με ενεργό cloud, αποσυνδέσου και χρησιμοποίησε το κανάλι επικοινωνίας για αίτημα διαγραφής.\"] },\n      { title: \"Ενημερώσεις\", paragraphs: [\"Η πολιτική μπορεί να ενημερωθεί όταν αλλάζουν οι λειτουργίες.\"] }\n    ] },\n    terms: { eyebrow: \"Πλαίσιο χρήσης\", title: \"Όροι χρήσης\", description: \"Βασικοί όροι και όρια ευθύνης για οικονομικά δεδομένα.\", sections: [\n      { title: \"Υπηρεσία ενημέρωσης\", paragraphs: [\"Το BoranTheGreat παρέχει εργαλεία αγοράς, καιρού, ειδήσεων, χαρτοφυλακίου και υπολογισμών για ενημέρωση.\"] },\n      { title: \"Δεν αποτελεί συμβουλή\", paragraphs: [\"Τιμές, περιλήψεις, υπολογισμοί, απαντήσεις BorAI και ειδοποιήσεις δεν αποτελούν επενδυτική, πιστωτική, φορολογική ή νομική συμβουλή.\"] },\n      { title: \"Ακρίβεια και καθυστέρηση\", paragraphs: [\"Δεδομένα τρίτων μπορεί να καθυστερούν, να είναι ελλιπή ή προσωρινά μη διαθέσιμα. Επιβεβαίωσε σημαντικά στοιχεία από επίσημες πηγές.\"] },\n      { title: \"Ευθύνη χρήστη\", bullets: [\"Προστάτευσε λογαριασμό και συσκευή.\", \"Έλεγξε ανεξάρτητα ειδοποιήσεις και υπολογισμούς.\", \"Μη χρησιμοποιείς την υπηρεσία παράνομα ή με τρόπο που επιβαρύνει το σύστημα.\"] },\n      { title: \"Διαθεσιμότητα\", paragraphs: [\"Συντήρηση, όρια API ή τεχνικά προβλήματα μπορεί να διακόψουν λειτουργίες. Δεν εγγυάται συνεχής πρόσβαση.\"] },\n      { title: \"Αλλαγές\", paragraphs: [\"Οι όροι μπορεί να ενημερωθούν. Η συνέχιση χρήσης σημαίνει αποδοχή των τρεχόντων όρων.\"] }\n    ] },\n    sources: { eyebrow: \"Εμπιστοσύνη δεδομένων\", title: \"Πηγές δεδομένων και ενημέρωση\", description: \"Δείχνει από πού προέρχονται τιμές, καιρός και ειδήσεις.\", sections: [\n      { title: \"Συνάλλαγμα\", bullets: [\"Frankfurter API για ισοτιμίες και ιστορικά δεδομένα.\", \"Οι κάρτες εμφανίζουν ώρα ενημέρωσης όπου είναι δυνατό.\"] },\n      { title: \"Κρυπτονομίσματα\", bullets: [\"CoinGecko για τιμές, μεταβολές, όγκο, κεφαλαιοποίηση και γραφήματα.\", \"CoinLore ως εφεδρική πηγή σε ορισμένες οθόνες.\"] },\n      { title: \"Χρυσός\", bullets: [\"Yahoo Finance ή το επίπεδο server για ενδεικτική τιμή ουγγιάς.\", \"Η τιμή γραμμαρίου μπορεί να διαφέρει από λιανικές τιμές.\"] },\n      { title: \"Καιρός\", bullets: [\"Open-Meteo Geocoding για αναζήτηση πόλης.\", \"Open-Meteo Forecast για τρέχοντα στοιχεία και πρόγνωση.\"] },\n      { title: \"Ειδήσεις και ημερολόγιο\", bullets: [\"GDELT για ειδήσεις ανά γλώσσα και κατηγορία.\", \"Finnhub για οικονομικό ημερολόγιο όταν υπάρχει κλειδί.\"] },\n      { title: \"Τεχνητή νοημοσύνη\", bullets: [\"OpenAI για απαντήσεις cloud του BorAI όταν υπάρχει κλειδί.\", \"Χωρίς κλειδί μπορεί να λειτουργεί τοπική βοήθεια.\"] },\n      { title: \"Πολιτική σφάλματος\", paragraphs: [\"Όταν μια πηγή δεν είναι διαθέσιμη πρέπει να εμφανίζεται σφάλμα, τελευταία γνωστή τιμή ή σαφώς σημειωμένη εφεδρική πηγή—όχι ψεύτικα ζωντανά δεδομένα.\"] }\n    ] },\n    contact: { eyebrow: \"Επικοινωνία\", title: \"Επικοινωνία με το BoranTheGreat\", description: \"Χρησιμοποίησε το επίσημο κοινωνικό κανάλι για σφάλματα, ιδέες ή σχόλια δεδομένων.\", sections: [\n      { title: \"Instagram\", paragraphs: [\"Ανάφερε συσκευή, διεύθυνση σελίδας και σαφή περιγραφή. Ένα στιγμιότυπο χωρίς ιδιωτικές πληροφορίες βοηθά.\"] },\n      { title: \"Για αναφορά σφάλματος\", bullets: [\"URL σελίδας.\", \"Συσκευή και browser.\", \"Περίπου ώρα.\", \"Στιγμιότυπο χωρίς προσωπικά ή μυστικά δεδομένα.\"] }\n    ] },\n    guide: { eyebrow: \"Κέντρο μάθησης\", title: \"Οδηγός και λεξικό οικονομικών\", description: \"Σύντομες εξηγήσεις βασικών όρων των αγορών.\", sections: [\n      { title: \"Παρακράτηση φόρου\", paragraphs: [\"Φόρος που αφαιρείται από τόκους ή επενδυτικό εισόδημα. Η καθαρή απόδοση μένει μετά την αφαίρεση.\"] },\n      { title: \"Κεφαλαιοποίηση αγοράς\", paragraphs: [\"Κυκλοφορούσα ποσότητα επί τρέχουσα τιμή. Δεν αποδεικνύει μόνη της ότι ένα στοιχείο είναι φθηνό ή ακριβό.\"] },\n      { title: \"Όγκος\", paragraphs: [\"Η αξία συναλλαγών σε μια περίοδο. Υψηλότερος όγκος συνήθως σημαίνει περισσότερη δραστηριότητα.\"] },\n      { title: \"Διαφορά αγοράς–πώλησης\", paragraphs: [\"Η διαφορά μεταξύ τιμής αγοράς και πώλησης και μέρος του κόστους συναλλαγής.\"] },\n      { title: \"Μεταβλητότητα\", paragraphs: [\"Πόσο γρήγορα και έντονα αλλάζει η τιμή. Μεγαλύτερη μεταβλητότητα μπορεί να σημαίνει μεγαλύτερο κίνδυνο.\"] },\n      { title: \"Διαφοροποίηση\", paragraphs: [\"Κατανομή αποταμιεύσεων σε διαφορετικούς κινδύνους. Δεν εξαλείφει τις ζημίες.\"] },\n      { title: \"Ειδοποίηση τιμής\", paragraphs: [\"Εργαλείο ελέγχου ή ειδοποίησης όταν εκπληρωθεί μια συνθήκη. Δεν εκτελεί αυτόματα συναλλαγή.\"] },\n      { title: \"Ασφαλέστερη χρήση\", bullets: [\"Μη βασίζεσαι σε μία πηγή.\", \"Σκέψου τον κίνδυνο μαζί με την απόδοση.\", \"Ζήτησε επαγγελματική γνώμη πριν χρησιμοποιήσεις δανεικά ή απαραίτητα χρήματα σε υψηλό κίνδυνο.\"] }\n    ] }\n  }\n};\n\nexport function StaticInfoPage({ kind }: { kind: InfoKind }) {\n  const pathname = usePathname();\n  const locale = getLocaleFromPath(pathname);\n  const page = content[locale][kind];\n\n  return (\n    <div className=\"space-y-6\">\n      <PageHero eyebrow={page.eyebrow} title={page.title} description={page.description}>\n        {kind === \"contact\" ? (\n          <a href=\"https://instagram.com/boranthegreat\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"inline-flex items-center gap-2 rounded-xl bg-mint px-4 py-3 font-black text-slate-950 transition hover:brightness-110\">\n            Instagram<ExternalLink className=\"h-4 w-4\" />\n          </a>\n        ) : kind === \"sources\" ? (\n          <Link href={localizedHref(pathname, \"/tools\")} className=\"inline-flex items-center gap-2 rounded-xl border border-mint/30 bg-mint/10 px-4 py-3 font-black text-mint transition hover:bg-mint/15\">\n            <Database className=\"h-4 w-4\" />{locale === \"tr\" ? \"Hesaplama araçlarını aç\" : locale === \"el\" ? \"Άνοιγμα εργαλείων\" : \"Open calculators\"}\n          </Link>\n        ) : (\n          <span className=\"inline-flex items-center gap-2 rounded-xl border border-mint/20 bg-mint/10 px-4 py-3 text-sm font-bold text-mint\"><ShieldCheck className=\"h-4 w-4\" />boranthegreat.xyz</span>\n        )}\n      </PageHero>\n\n      {kind === \"privacy\" ? <DataPrivacyControls /> : null}\n\n      <div className=\"grid gap-4 lg:grid-cols-2\">\n        {page.sections.map((section) => (\n          <article key={section.title} className=\"rounded-2xl border border-white/10 bg-slate-950/45 p-5 sm:p-6\">\n            <h2 className=\"text-lg font-black text-white\">{section.title}</h2>\n            {section.paragraphs?.map((paragraph) => <p key={paragraph} className=\"mt-3 text-sm leading-7 text-slate-300\">{paragraph}</p>)}\n            {section.bullets ? <ul className=\"mt-3 space-y-2 text-sm leading-7 text-slate-300\">{section.bullets.map((bullet) => <li key={bullet} className=\"flex gap-3\"><span className=\"mt-2.5 h-1.5 w-1.5 shrink-0 rounded-full bg-mint\" />{bullet}</li>)}</ul> : null}\n          </article>\n        ))}\n      </div>\n    </div>\n  );\n}\n",
  "components/enhancements/locale.ts": "export type BtgLocale = \"tr\" | \"en\" | \"el\";\n\nexport function getLocaleFromPath(pathname: string): BtgLocale {\n  const firstSegment = pathname.split(\"/\").filter(Boolean)[0];\n  if (firstSegment === \"tr\" || firstSegment === \"en\" || firstSegment === \"el\") {\n    return firstSegment;\n  }\n  return \"tr\";\n}\n\nexport function localizedHref(pathname: string, target: string): string {\n  const locale = getLocaleFromPath(pathname);\n  const normalizedTarget = target.startsWith(\"/\") ? target : `/${target}`;\n  return `/${locale}${normalizedTarget === \"/\" ? \"\" : normalizedTarget}`;\n}\n",
  "app/tools/page.tsx": "import type { Metadata } from \"next\";\nimport { AlertWizard } from \"@/components/enhancements/AlertWizard\";\nimport { FinanceCalculatorHub } from \"@/components/enhancements/FinanceCalculatorHub\";\nimport { PageHero } from \"@/components/enhancements/PageHero\";\nimport { ShareCardGenerator } from \"@/components/enhancements/ShareCardGenerator\";\n\nexport const metadata: Metadata = { title: \"Finans Araçları | BoranTheGreat\", description: \"BoranTheGreat finans hesaplama ve paylaşım araçları.\" };\nexport default function Page() { return <div className=\"space-y-6\"><PageHero eyebrow=\"BoranTheGreat Lab\" title=\"Hesapla, planla ve paylaş.\" description=\"Finans hesaplamaları, kolay alarm taslağı ve paylaşım kartı tek ekranda.\" /><FinanceCalculatorHub /><AlertWizard /><ShareCardGenerator /></div>; }\n",
  "app/privacy/page.tsx": "import { StaticInfoPage } from \"@/components/enhancements/StaticInfoPage\";\nexport default function Page() { return <StaticInfoPage kind=\"privacy\" />; }\n",
  "app/terms/page.tsx": "import { StaticInfoPage } from \"@/components/enhancements/StaticInfoPage\";\nexport default function Page() { return <StaticInfoPage kind=\"terms\" />; }\n",
  "app/data-sources/page.tsx": "import { StaticInfoPage } from \"@/components/enhancements/StaticInfoPage\";\nexport default function Page() { return <StaticInfoPage kind=\"sources\" />; }\n",
  "app/contact/page.tsx": "import { StaticInfoPage } from \"@/components/enhancements/StaticInfoPage\";\nexport default function Page() { return <StaticInfoPage kind=\"contact\" />; }\n",
  "app/guide/page.tsx": "import { StaticInfoPage } from \"@/components/enhancements/StaticInfoPage\";\nexport default function Page() { return <StaticInfoPage kind=\"guide\" />; }\n"
};

function absolute(relativePath) { return path.join(root, relativePath); }
function exists(relativePath) { return fs.existsSync(absolute(relativePath)); }
function read(relativePath) { return fs.readFileSync(absolute(relativePath), "utf8"); }
function write(relativePath, content) {
  const target = absolute(relativePath);
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, content, "utf8");
  console.log(`✓ ${relativePath}`);
}

function patchAppShell() {
  const relativePath = "components/AppShell.tsx";
  if (!exists(relativePath)) throw new Error("components/AppShell.tsx bulunamadı; değişiklikler commit edilmeyecek.");
  let text = read(relativePath);
  const importAnchor = 'import { ThemePicker } from "@/components/ThemePicker";';
  const imports = [
    'import { AlertDraftBridge } from "@/components/enhancements/AlertDraftBridge";',
    'import { FooterUpgradeLinks } from "@/components/enhancements/FooterUpgradeLinks";',
    'import { HomeEnhancementPanel } from "@/components/enhancements/HomeEnhancementPanel";',
    'import { LocalizedBrandLink } from "@/components/enhancements/LocalizedBrandLink";',
    'import { MobileBottomNavigation } from "@/components/enhancements/MobileBottomNavigation";',
    'import { QuickToolsButton } from "@/components/enhancements/QuickToolsButton";'
  ];
  if (!text.includes(imports[0])) {
    if (!text.includes(importAnchor)) throw new Error("AppShell import bölümü tanınamadı.");
    text = text.replace(importAnchor, `${importAnchor}\n${imports.join("\n")}`);
  }

  if (!text.includes("<LocalizedBrandLink")) {
    const brandPattern = /<Link\s+href=(?:"https:\/\/instagram\.com\/boranthegreat"|"\/")[\s\S]*?className="group"\s*>/;
    const match = text.match(brandPattern);
    if (!match || match.index === undefined) throw new Error("AppShell logo bağlantısı tanınamadı.");
    text = text.replace(brandPattern, '<LocalizedBrandLink className="group">');
    const closeIndex = text.indexOf("</Link>", match.index);
    if (closeIndex === -1) throw new Error("AppShell logo kapanışı bulunamadı.");
    text = `${text.slice(0, closeIndex)}</LocalizedBrandLink>${text.slice(closeIndex + 7)}`;
    if (!/<Link\b/.test(text)) text = text.replace('import Link from "next/link";\n', "");
  }

  if (!text.includes('className="btg-desktop-cursor-effects"')) text = text.replace('      <CursorEffects />', '      <div className="btg-desktop-cursor-effects"><CursorEffects /></div>');
  if (!text.includes('className="btg-header-actions')) text = text.replace('className="flex flex-wrap items-center justify-end gap-2"', 'className="btg-header-actions flex flex-wrap items-center justify-end gap-2"');
  if (!text.includes('className="btg-desktop-navigation"')) text = text.replace('              <Navigation />', '              <div className="btg-desktop-navigation"><Navigation /></div>');
  if (!text.includes("<QuickToolsButton />")) text = text.replace("                <PwaInstallButton />", "                <QuickToolsButton />\n                <PwaInstallButton />");

  if (!text.includes("<HomeEnhancementPanel />")) {
    const exactMain = '      <main className="mx-auto max-w-7xl px-4 py-8 sm:px-6 lg:px-8">{children}</main>';
    if (!text.includes(exactMain)) throw new Error("AppShell main bölümü tanınamadı.");
    text = text.replace(exactMain, `      <main className="mx-auto max-w-7xl px-4 py-8 sm:px-6 lg:px-8">
        {children}
        <AlertDraftBridge />
        <HomeEnhancementPanel />
      </main>`);
  } else if (!text.includes("<AlertDraftBridge />")) {
    text = text.replace("        <HomeEnhancementPanel />", "        <AlertDraftBridge />\n        <HomeEnhancementPanel />");
  }

  if (!text.includes("<MobileBottomNavigation />")) text = text.replace("      <AIAssistantWidget />", "      <AIAssistantWidget />\n      <MobileBottomNavigation />");
  if (!text.includes("<FooterUpgradeLinks />")) {
    const closingFooter = text.indexOf("</footer>");
    if (closingFooter === -1) throw new Error("AppShell footer bölümü bulunamadı.");
    text = `${text.slice(0, closingFooter)}  <FooterUpgradeLinks />\n      ${text.slice(closingFooter)}`;
  }
  write(relativePath, text);
}

function appendGlobalStyles() {
  const relativePath = ["app/globals.css", "styles/globals.css"].find(exists);
  if (!relativePath) return;
  let text = read(relativePath);
  const marker = "/* BTG_COMPLETE_UPGRADE_V2 */";
  if (text.includes(marker)) return;
  text += `

${marker}
html { scroll-behavior: smooth; }
@media (max-width: 767px) {
  .btg-desktop-navigation, .btg-desktop-cursor-effects, .cursor-effect, .cursor-trail, .cursor-glow, [data-cursor-effect] { display: none !important; }
  .btg-header-actions { max-width: 100%; flex-wrap: nowrap !important; justify-content: flex-start !important; overflow-x: auto; padding-bottom: 0.25rem; scrollbar-width: none; }
  .btg-header-actions::-webkit-scrollbar { display: none; }
  .btg-header-actions > * { flex: 0 0 auto; }
  main { padding-bottom: max(7rem, env(safe-area-inset-bottom)); }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { scroll-behavior: auto !important; animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; transition-duration: 0.01ms !important; }
}
`;
  write(relativePath, text);
}

function writeLocalizedRoutes() {
  const appRoot = absolute("app");
  const roots = fs.readdirSync(appRoot, { withFileTypes: true }).filter((e) => e.isDirectory() && ["[locale]", "[lang]"].includes(e.name)).map((e) => e.name);
  const routeNames = ["tools", "privacy", "terms", "data-sources", "contact", "guide"];
  for (const localeRoot of roots) for (const route of routeNames) write(`app/${localeRoot}/${route}/page.tsx`, read(`app/${route}/page.tsx`));
}

